comms.text:
@1 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@2 פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא אֲתֵיב יַת חֵמְתִי מֵעַל בְּנֵי יִשְׂרָאֵל בִּדְקַנֵי יַת קִנְאָתִי בֵּינֵיהוֹן וְלָא שֵׁיצֵיתִי יַת בְּנֵי יִשְׂרָאֵל בְּקִנְאָתִי:
@3 בְּכֵן אֵימַר הָא אֲנָא גְזַר לֵיהּ יַת קְיָמִי שְׁלָם:
@4 וּתְהֵי לֵיהּ וְלִבְנוֹהִי בַּתְרוֹהִי קְיַם כְּהֻנַת עֲלָם חֲלַף דִי קַנֵי קֳדָם אֱלָהֵהּ וְכַפֵּר עַל בְּנֵי יִשְׂרָאֵל:
@5 וְשׁוּם גַבְרָא בַּר יִשְרָאֵל קְטִילָא דִי אִתְקְטֵל עִם מִדְיָנֵיתָא זִמְרִי בַּר סָלוּא רַב בֵּית אַבָּא לְבֵית שִׁ מְעוֹן:
@6 וְשׁוּם אִתְּתָא דְאִתְקְטִילַת מִדְיָנֵיתָא כָּזְבִּי בַּת צוּר רֵישׁ אוּמֵי בֵּית אַבָּא בְּמִדְיָן הוּא:
@7 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@8 אָעֵק יַת מִדְיָנָאֵי וְתִקְטְלוּן יָתְהוֹן:
@9 אֲרֵי מְעִיקִין אִינוּן לְכוֹן בְּנִכְלֵיהוֹן דִי נְכִילוּ לְכוֹן עַל עֵיסַק פְּעוֹר וְעַל עֵיסַק כָּזְבִּי בַּת רַבָּא דְמִדְיָן אֲחַתְהוֹן דְאִתְקְטִילַת בְּיוֹמָא דְמוֹתָנָא עַל עֵיסַק פְּעוֹר:
@11 וַהֲוָה בָּתַר מוֹתָנָא וַאֲמַר יְיָ לְמשֶׁה וּלְאֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא לְמֵימָר:
@12 קַבִּילוּ יַת חוּשְׁבַּן כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא לְבֵית אֲבָהַתְהוֹן כָּל נָפֵיק חֵילָא בְּיִשְׂרָאֵל:
@13 וּמַלִיל משֶׁה וְאֶלְעָזָר כַּהֲנָא וַאֲמָרוּ לְמִמְנֵי יָתְהוֹן בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירִיחוֹ לְמֵימָר:
@14 מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּבְנֵי יִשְׂרָאֵל דִנְפָקוּ מֵאַרְעָא דְמִצְרָיִם:
@15 רְאוּבֵן בּוּכְרָא דְיִשְׂרָאֵל בְּנֵי רְאוּבֵן חֲנוֹךְ זַרְעִית חֲנוֹךְ לְפַלוּא זַרְעִית פַּלוּא:
@16 לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְכַרְמִי זַרְעִית כַּרְמִי:
@17 אִלֵין זַרְעֲיַת רְאוּבֵן וַהֲווֹ מִנְיָנֵיהוֹן אַרְבְּעִין וּתְלָתָא אַלְפִין וּשְׁבַע מְאָה וּתְּלָתִין:
@18 וּבְנֵי פַלוּא אֱלִיאָב:
@19 וּבְנֵי אֱלִיאָב נְמוּאֵל וְדָתָן וַאֲבִירָם הוּא דָתָן וַאֲבִירָם מְעַרְעֵי כְּנִשְׁתָּא דְאִתְכְּנָשׁוּ עַל משֶׁה וְעַל אַהֲרֹן בִּכְנִשְׁתָּא דְקֹרַח בְּאִתְכַּנוֹשֵׁיהוֹן עַל יְיָ:
@20 וּפְתָחַת אַרְעָא יַת פּוּמָהּ וּבְלָעַת יָתְהוֹן וְיָת קֹרַח בְּמוֹתָא דִכְנִשְׁתָּא כַּד אֲכָלַת אֵשָׁתָא יַת מָאתָן וְחַמְשִׁין גַבְרָא וַהֲווֹ לְאָת:
@21 וּבְנֵי קֹרַח לָא מִיתוּ:
@22 בְּנֵי שִׁמְעוֹן לְזַרְעֲיַתְהוֹן לִנְמוּאֵל זַרְעִית נְמוּאֵל לְיָמִין זַרְעִית יָמִין לְיָכִין זַרְעִית יָכִין:
@23 לְזֶרַח זַרְעִית זֶרַח לְשָׁאוּל זַרְעִית שָׁאוּל:
@24 אִלֵין זַרְעֲיַת שִׁמְעוֹן עַשְׂרִין וּתְרֵין אַלְפִין וּמָאתָן:
@25 בְּנֵי גָד לְזַרְעֲיַתְהוֹן לִצְפוֹן זַרְעִית צְפוֹן לְחַגִי זַרְעִית חַגִי לְשׁוּנִי זַרְעִית שׁוּנִי:
@26 לְאָזְנִי זַרְעִית אָזְנִי לְעֵרִי זַרְעִית עֵרִי:
@27 לַאֲרוֹד זַרְעִית אֲרוֹדִי לְאַרְאֵלִי זַרְעִית אַרְאֵלִי:
@28 אִלֵין זַרְעֲיַת בְּנֵי גָד לְמִנְיָנֵהוֹן אַרְבְּעִין אַלְפִין וַחֲמֵשׁ מְאָה:
@29 בְּנֵי יְהוּדָה עֵר וְאוֹנָן וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִכְנָעַן:
@30 וַהֲווֹ בְנֵי יְהוּדָה לְזַרְעֲיַתְהוֹן לְשֵׁלָה זַרְעִית שֵׁלָה לְפֶרֶץ זַרְעִית פֶּרֶץ לְזֶרַח זַרְעִית זָרַח:
@31 וַהֲווֹ בְנֵי פֶרֶץ לְחֶצְרוֹן זַרְעִית חֶצְרוֹן לְחָמוּל זַרְעִית חָמוּל:
@32 אִלֵין זַרְעֲיַת יְהוּדָה לְמִנְיָנֵיהוֹן שִׁבְעִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@33 בְּנֵי יִשָשׂכָר לְזַרְעֲיַתְהוֹן תּוֹלָע זַרְעִית תּוֹלָע לְפֻוָה זַרְעִית פּוּנִי:
@34 לְיָשׁוּב זַרְעִית יָשׁוּב לְשִׁמְרוֹן זַרְעִית שִׁמְרוֹן:
@35 אִלֵין זַרְעֲיַת יִשָׂשׂכָר לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבְּעָה אַ:לפִין וּתְלַת מְאָה:
@36 בְּנֵי זְבוּלוּן לְזַרְעֲיַתְהוֹן לְסֶרֶד זַרְעִית סֶרֶד לְאֵלוֹן זַרְעִית אֵלוֹן לְיַחְלְאֵל זַרְעִית יַחְלְאֵל:
@37 אִלֵין זַרְעֲיַת זְבוּלוּן לְמִנְיָנֵיהוֹן שִׁתִּין אַלְפִין:וְחֲמֵשׁ מְאָה:
@38 בְּנֵי יוֹסֵף לְזַרְעֲיַתְהוֹן מְנַשֶׁה וְאֶפְרָיִם:
@39 בְּנֵי מְנַשֶׁה לְמָכִיר זַרְעִית מָכִיר וּמָכִיר אוֹלִיד יַת גִלְעָד לְגִלְעָד זַרְעִית גִלְעָד:
@40 אִלֵין בְּנֵי גִלְעָד אִיעֶזֶר זַרְעִית אִיעֶזֶר לְחֵלֶק זַרְעִית חֵלֶק:
@41 וְאַשְׂרִיאֵל זַרְעִית אַשְׂרִיאֵלִי וְשֶׁכֶם זַרְעִית שֶׁכֶם:
@42 וּשְׁמִידָע זַרְעִית שְׁמִידָע וְחֵפֶר זַרְעִית חֵפֶר:
@43 וּצְלָפְחָד בַּר חֵפֶר לָא הֲווֹ לֵיהּ בְּנִין אֱלָהֵין בְּנָן וְשׁוּם בְּנַת צְלָפְחָד מַחְלָה וְנוֹעָה חָגְלָה מִלְכָּה וְתִרְצָה:
@44 אִלֵין זַרְעֲיַת מְנַשֶׁה וּמִנְיָנֵיהוֹן חַמְשִׁין וּתְרֵין אַלְפִין וּשְׁבַע מְאָה:
@45 אִלֵין בְּנֵי אֶפְרַיִם לְזַרְעֲיַתְהוֹן לְשׁוּתֶלַח זַרְעִית שׁוּתֶלַח לְבֶכֶר זַרְעִית בֶּכֶר לְתַחַן זַ:רעִית תַּחַן:
@46 וְאִלֵין בְּנֵי שׁוּתָלַח לְעֵרָן זַרְעִית עֵרָן:
@47 אִלֵין זַרְעֲיַת בְּנֵי אֶפְרַיִם לְמִנְיָנֵיהּוֹן תְּלָתִין וּתְרֵין אַלְפִין וַחֲמֵשׁ מְאָה אִלֵין בְּנֵי יוֹסֵף לְזַרְעֲיַתְהּוֹן:
@48 בְּנֵי בִנְיָמִין לְזַרְעֲיַתְהוֹן לְבֶלַע זַרְעִית בֶּלַע לְאַשְׁבֵּל זַרְעִית אַשְׁבֵּל לַאֲחִירָם זַרְעִית אֲחִירָם:
@49 לִשְׁפוּפָם זַרְעִית שְׁפוּפָם לְחוּפָם זַרְעִית חוּפָם:
@50 וַהֲווֹ בְנֵי בֶלַע אַרְדְ וְנַעֲמָן זַרְעִית הָאַרְדִי לְנַעֲמָן זַרְעִית נַעֲמִי:
@51 אִלֵין בְּנֵי בִנְיָמִן לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְשִׁית מְאָה:
@52 אִלֵין בְּנֵי דָן לְזַרְעֲיַתְהוֹן לְשׁוּחָם זַרְעִית שׁוּחָם אִלֵין זַרְעֲיַת דָן לְזַרְעֲיַתְהוֹן:
@53 כָל זַרְעֲיַת שׁוּחָם לְמִנְיָנֵיהוֹן שִׁתִּין וְאַרְבַּע אַלְפִין וְאַרְבַּע מְאָה:
@54 בְּנֵי אָשֵׁר לְזַרְעֲיַתְהוֹן לְיִמְנָה זַרְעִית יִמְנָה לְיִשְׁוִי זַרְעִית יִשְׁוִי לִבְרִיעָה זַרְעִית בְּרִיעָה:
@55 לִבְנֵי בְרִיעָה לְחֵבֶר זַרְעִית חֵבֶר לְמַלְכִּיאֵל זַרעִית מַלְכִּיאֵל:
@56 וְשׁוּם:בַּת אָשֵׁר סָרַח:
@57 אִלֵין זַרְעֲיַת בְּנֵי אָשֵׁר לְמִנְיָנֵיהוֹן חַמְשִׁין וּתְלָתָא אַלְפִין:ואַ:רבַּע מְאָה:
@58 בְּנֵי נַפְתָּלִי לְזַרְעֲיַתְהוֹן לְיַחְצְאֵל זַרְעִית יַחְצְאֵל לְגוּנִי זַרְעִית גוּנִי:
@59 לְיֵצֶר זַרְעִית יֵצֶר לְשִׁלֵם זַרְעִית שִׁלֵם:
@60 אִלֵין זַרְעֲיַת נַפְתָּלִי לְזַרְעֲיַתְהוֹן וּמִנְיָנֵיהוֹן אַרְבְּעִין וְחַמְשָׁא אַלְפִין וְאַרְבַּע מֵאָה:
@61 אִלֵין מִנְיָנֵי בְּנֵי יִשְׂרָאֵל שִׁית מְאָה וְחַד אַלְפִין שְׁבַע מְאָה וּתְלָתִין:
@62 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@63 לְאִלֵין תִּתְפְּלֵיג אַרְעָא בְּאַחֲסָנָא בְּמִנְיַן שְׁמָהָן:
@64 לְסַגִיאֵי תִּסְגוּן אַחֲסַנְתְּהוֹן וְלִזְעֵירֵי תַּזְעֲרוּן אַחֲסַנְתְּהוֹן גְבַר לְפוּם מִנְיָנוֹהִי תִּתְיְהֵב אַחֲסַנְתֵּיהּ:
@65 בְּרַם בְּעַדְבָא תִּתְפְּלֵיג יַת אַרְעָא לִשְׁמָהָן שִׁבְטֵי אֲבָהָתְהוֹן יַחְסְנוּן:
@66 עַל פּוּם עַדְבָא תִּתְפְּלֵיג אַחֲסַנְתְּהוֹן בֵּין סַגִיאֵי לִזְעֵירֵי:
@67 וְאִלֵין מִנְיָנֵי לֵוָאֵי לְזַרְעֲיַתְהוֹן לְגֵרְשׁוֹן זַרְעִית גֵרְשׁוֹן לִּקְהָת זַרְעִית קְהָת לִמְרָרִי זַרְעִית מְרָרִי:
@68 אִלֵין זַרְעֲיַת לֵוִי זַרְעִית לִבְנִי זַרְעִית חֶבְרוֹן זַרְעִית מַחְלִי זַרְעִית מוּשִׁי זַרְעִית קֹרַח וּקְהָת אוֹלִיד יָת עַמְרָם:
@69 וְשׁוּם אִתַּת עַמְרָם יוֹכֶבֶד בַּת לֵוֵי דִילֵדַת יָתַהּ לְלֵוִי בְּמִצְרָיִם וִילֵידַת לְעַמְרָם יָת אַהֲרֹן וְיָת משֶׁה וְיָת מִרְיָם אֲחַתְהוֹן:
@70 וְאִתְיְלִיד לְאַהֲרֹן יַת נָדָב וְיַת אֲבִיהוּא יַת אֶלְעָזָר וְיַת אִיתָמָר:
@71 וּמִית נָדָב וַאֲבִיהוּא בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ:
@72 וַהֲווֹ מִנְיָנֵיהוֹן עַשְׂרִין וּתְלָתָא אַלְפִין כָּל דְכוּרָא מִבַּר יַרְחָא וּלְעֵילָא אֲרֵי לָא אִתְמְנִיאוּ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲרֵי לָא אִתְיְהִיבַת לְהוֹן אַחֲסָנָא בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@73 אִלֵין מִנְיָנֵי משֶׁה וְאֶלְעָזָר כַּהֲנָא דִי מְנוֹ יַת בְּנֵי יִשְׂרָאֵל בְּמֵישְׁרַיָא דְמוֹאָב עַל יַרְדְנָא דִירֵיחוֹ:
@74 וּבְאִלֵין לָא הֲוָה גְבַר מִמִנְיָנֵי משֶׁה וְאַהֲרֹן כַּהֲנָא דִי מְנוֹ יָת בְּנֵי יִשְׂרָאֵל בְּמַדְבְּרָא דְסִינָי:
@75 אֲרֵי אֲמַר יְיָ לְהוֹן מֵימַת יְמוּתוּן בְּמַדְבְּרָא וְלָא אִשְׁתְּאַר מִנְהוֹן אֱנַשׁ אֶלָהֵן כָּלֵב בַּר יְפֻנֶה וִיהוֹשֻׁעַ בַּר נוּן:
@76 וְקָרֵיבָא בְּנַת צְלָפְחָד בַּר חֵפֶר בַּר גִלְעָד בַּר מָכִיר בַּר מְנַשֶׁה לְזַרְעֲיַת מְנַשֶׁה בַּר יוֹסֵף וְאִלֵין שְׁמָהַת בְּנָתֵיהּ מַחְלָה נוֹעָה וְחָגְלָה וּמִלְכָּה וְתִרְצָה:
@77 וְקָמָן קֳדָם משֶׁה וְקֳדָם אֶלְעָזָר כַּהֲנָא וְקֳדָם רַבְרְבַיָא וְכָל כְּנִשְׁתָּא בִּתְרַע מַשְׁכַּן זִמְנָא לְמֵימָר:
@78 אָבוּנָא מִית בְּמַדְבְּרָא וְהוּא לָא הֲוָה בְּגוֹ כְנִשְׁתָּא דְאִזְדַמָנוּ עַל יְיָ בְּכְנִשְׁתָּא דְקֹרַח אֲרֵי בְחוֹבֵיהּ מִית וּבְנִין לָא הֲווֹ לֵיהּ:
@79 לְמָא יִתְמְנַע שְׁמָא דַאֲבוּנָא מִגוֹ זַרְעִיתֵיהּ אֲרֵי לֵית לֵיהּ בָּר הַב לָנָא אַחֲסָנָא בְּגוֹ אֲחֵי אָבוּנָא:
@80 וְקָרֵב משֶׁה יָת דִינְהוֹן קֳדָם יְיָ:
@81 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@82 יָאוּת בְּנַת צְלָפְחָד מְמַלְלָן מִתַּן תִּתֵּן לְהוֹן אֲחוּדַת אַחֲסָנָא בְּגוֹ אֲחֵי אֲבוּהֶן וְתַעֲבַר יַת אַחֲסָנַת אֲבוּהֶן לָהֶן:
@83 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵיל לְמֵימָר גְבַר אֲרֵי יְמוּת וּבַר לֵית לֵיהּ וְתַעַבְרוּן יָת אַחֲסַנְתֵּיהּ לִּבְרַתֵּיהּ:
@84 וְאִם לֵית לֵיהּ בְּרַתָּא וְתִתְּנוּן יָת אַחֲסַנְתֵּיה לַאֲחוֹהִי:
@85 וְאִם לֵית לֵיהּ אַחִין וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְאֲחֵי אֲבוּהִי:
@86 וְאִם לֵית אַחִין לַאֲבוּהִי וְתִתְּנוּן יָת אַחֲסַנְתֵּיהּ לְקָרִיבֵיהּ דְקָרֵיבּ לֵיהּ מִזַרְעִיתֵיהּ וְיֵרַת יָתַהּ וּתְהֵי לִבְנֵי יִשְׂרָאֵל לִגְזֵירַת דִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@87 וַאֲמַר יְיָ לְמשֶׁה סַק לְטוּרָא דַעֲבָרָאֵי הָדֵין וַחֲזֵי יָת אַרְעָא דִי יְהָבִית לִבְנֵי יִשִׂרָאֵל:
@88 וְתֶחֱזֵי יָתָהּ וְתִתְכְנֵּשׁ לְעַמָיךְ אַף אָתְּ כְּמָא דִי אִתְכְּנִישׁ אַהֲרֹן אָחוּךְ:
@89 כְּמָא דִסָרֵיבְתּוּן עַל מֵימְרִי בְּמַדְבְּרָא דְצִן בְּמַצוּת כְּנִשְׁתָּא לְקַדָשׁוּתִי בְמַיָא לְעֵינֵיהוֹן אִנוּן מֵי מַצוּת רְקָם מַדְבְּרָא דְצִן:
@90 וּמַלִיל משֶׁה קֳדָם יְיָ לְמֵימָר:
@91 יְמַנֵי יְיָ אֱלָהָא רוּחַיָא לְכָל בִּשְׂרָא גְבַר עַל כְּנִשְׁתָּא:
@92 דִי יִפּוֹק קֳדָמֵיהוֹן וְדִי יֵעוֹל קֳדָמֵיהוֹן וְדִי יַפֵּקִנוּן וְדִי יָעֵלִינוּן וְלָא תְהֵי כְּנִשְׁתָּא דַיְיָ כְּעָנָא דִי לֵית לְהֵן רָעֵי:
@93 וַאֲמַר יְיָ לְמשֶׁה דְבַר לָךְ יָת יְהוֹשֻׁעַ בַּר נוּן גְבַר דִי רוּחַ נְבוּאָה בֵּיהּ וְתִסְמוֹךְ יָת יְדָךְ עֲלוֹהִי:
@94 וּתְקֵים יָתֵיהּ לָקֳדָם אֶלְעָזָר כַּהֲנָא וְלָקֳדָם כָּל כְּנִשְׁתָּא וּתְפַקֵד יָתֵיהּ לְעֵינֵיהוֹן:
@95 וְתִתֵּן מִזִיוָךְ עֲלוֹהִי בְּדִיל דִי יְקַבְּלוּן מִנֵיהּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל:
@96 וְלִקֳדָם אֶלְעָזָר כַּהֲנָא יְקוּם וְיִשְׁאַל לֵיהּ בְּדִין אוּרַיָא קֳדָם יְיָ עַל מֵימְרֵיהּ יְהוֹן נַפְקִין וְעַל מֵימְרֵא יְהוֹן עָאלִין הוּא וְכָל בְּנֵי יִשְׂרָאֵל עִמֵיהּ וְכָל כְּנִשְׁתָּא:
@97 וַעֲבַד משֶׁה כְּמָא דִי פַקֵיד יְיָ יָתֵיהּ וּדְבַר יָת יְהוֹשֻׁע וַאֲקִימֵיהּ קֳדָם אֶלְעָזָר כַּהֲנָא וּקְדָם כָּל כְּנִשְׁתָּא:
@98 וּסְמַךְ יָת יְדוֹהִי עֲלוֹהִי וּפַקְדֵיהּ כְּמָא דִי מַלִיל יְיָ בִּידָא דְמשֶׁה:
@99 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@100 פַקֵיד יָת בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן יָת קוּרְבָּנִי לְחֵם סִדוּר לְקוּרְבָּנַי לְאִתְקַבָּלָא בְּרַעֲוָא תִּטְרוּן לְקָרָבָא קֳדָמַי בְּזִמְנֵיהּ:
@101 וְתֵימַר לְהוֹן דֵין קוּרְבָּנָא דִי תְקַרְבוּן קֳדָם יְיָ אִימְּרִין בְּנֵי שְׁנָא שַׁלְמִין תְּרֵין לְּיוֹמָא עֲלָתָא תְּדִירָא:
@102 יָת אִמְרָא חָד תַּעֲבֵד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵד בֵּין שִׁמְשַׁיָא:
@103 וְחָד מִן עַשְׂרָא בִּתְלַת סָאִין סוּלְתָּא לְמִנְחָתָא דְפִילָא בִּמְשַׁח כְּתִישָׁא רַבְעוּת הִינָא:
@104 עֲלָתָא תְּדִירָא דְאִתְעֲבִידָא בְּטוּרָא דְסִינַי לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@105 וְנִסְכֵּיהּ רַבְעוּת הִינָא לְאִמְרָא חָד בְּקוּדְשָׁא יִתְנַסַךְ נִסוּךְ דַחֲמַר עַתִּיק קֳדָם יְיָ:
@106 וְיָת אִמְרָא תִנְיָנָא תַּעֲבֵיד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכֵּיהּ תַּעְבֵיד קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@107 וּבְיוֹמָא דְשַׁבַּתָּא תְּרֵין אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין וּתְרֵין עִשְׂרוֹנִין סוּלְתָּא דְמִנְחָתָא דְפִילָא בִּמְשַׁח וְנִסְכֵּיהּ:
@108 עֲלַת שַׁבְּתָא דְתִּתְעֲבֵיד בְּשַׁבַּתָּא עַל עֲלָתָא תְּדִירָא וְנִסְכַּהּ:
@109 וּבְרֵישֵׁי יַרְחֵיכוֹן תְּקַרְבוּן עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תּוֹרֵי תְּרֵין וּדְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@110 וּתְלָתָא עִשְׂרוֹנִין סוּלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְתוֹרָא חָד וּתְרֵין עִשְׂרוֹנִין סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְדִכְרָא חָד:
@111 וְעִשְׂרוֹנָא עִשְׂרוֹנָא סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח לְאִמְרָא חָד עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@112 וְנִסְכֵּיהוֹן פַּלְגוּת הִינָא יְהֵי לְתוֹרָא וְתַלְתּוּת הִינָא לְדִכְרָא וְרַבְעוּת הִינָא לְאִמְרָא חַמְרָא דָא עֲלַת רֵישׁ יַרְחָא בְּאִתְחַדָתוּתֵיהּ כֵּן לְכָל רֵישֵׁי יַרְחֵי שַׁתָּא:
@113 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא קֳדָם יְיָ עַל עֲלָתָא תְּדִירָא יִתְעֲבֵד וְנִסְכֵּיהּ:
@114 וּבְיַרְחָא קַדְמָאָה בְּאַרְבַּעַת עַשְׂרָא יוֹמָא לְיַרְחָא פִּסְחָא קֳדָם יְיָ:
@115 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא שַׁבְעָא יוֹמִין פַּטִיר יִתְאָכֵל:
@116 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עֲבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@117 וּתְקַרְבוּן קוּרְבָּנָא עֲלָתָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד וְשַׁבְעָא אִימְרִין בְּנֵי שְׁנָא שַׁלְמִין יְהוֹן לְכוֹן:
@118 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִּמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא וּתְרֵין עִשְׂרוֹנִין לְדִכְרָא תַּעְבְּדוּן:
@119 עִשְׂרוֹנָא עִשְׂרוֹנָא תַּעֲבֵיד לְאִמְרָא חָד כֵּן לְשַׁבְעָא אִימְרִין:
@120 וּצְפִירָא דְחַטָאתָא חָד לְכַפָּרָא עֲלֵיכוֹן:
@121 בַּר מֵעֲלַת צַפְרָא דְהִּיא עֲלַת תְּדִירָא תַּעְבְּדוּן יָת אִלֵין:
@122 כְּאִלֵין תַּעַבְדוּן לְיוֹמָא שַׁבְעָא יוֹמִין לְחֵם קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ עַל עֲלָתָא תְדִירָא יִתְעֲבֵיד וִנִסִכֵּיהּ:
@123 וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִיבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@124 וּבְיוֹמָא דְבִכּוּרַיָא בְּקָרוֹבֵיכוֹן מִנְחֲתָא חֲדַתָּא קֳדָם יְיָ בְּעַצְרָתֵיכוֹן מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן:
@125 וּתְקַרְבוּן עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּרֵין וּדְכַר חָד שַׁבְעָא אִימְרִין בְּנֵי שְׁנָא:
@126 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@127 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִמְרָא חָד לְשַׁבְעָא אִימְרִין:
@128 צְפִיר בַּר עִזִין חָד לְכַפָּרָא עֲלֵיכוֹן:
@129 בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתֵהּ תַּעְבְּדוּן שַׁלְמִין יְהוֹן לְכוֹן וְנִסְכֵּיהוֹן:
@130 וּבְיַרְחָא שְׁבִיעָאָה בְּחָד לְיַרְחָא מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן יוֹם יַבָּבָא יְהֵי לְכוֹן:
@131 וְתַעַבְדוּן עֲלָתָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@132 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא:
@133 וְעִשְׂרוֹנָא חָד לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@134 וּצְפִיר בַּר עִזִין חָד לְחַטָאתָא לְכַפָּרָא עֲלֵיכוֹן:
@135 בַּר מֵעֲלַת יַרְחָא וּמִנְחָתַהּ וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן כִּדְחָזֵי לְהוֹן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא קֳדָם יְיָ:
@136 וּבְעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן כָּל עִבִידְתָּא לָא תַעַבְדוּן:
@137 וּתְקָרְבוּן עֲלָתָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא תּוֹר בַּר תּוֹרֵי חָד דְכַר חָד אִימְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין יְהוֹן לְכוֹן:
@138 וּמִנְחַתְהוֹן סֻלְתָּא דְפִילָא בִמְשָׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד:
@139 עִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְשַׁבְעָא אִימְרִין:
@140 צְפִיר בַּר עִזִין חָד חַטָּאתָא בַּר מֵחַטָאתָא דְכִפוּרַיָא וַעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@141 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעַבְדוּן וּתְחַגוּן חַגָא קֳדָם יְיָ שַׁבְעָא יוֹמִין:
@142 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹרִין בְּנֵי תוֹרֵי תְּלַת עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין יְהוֹן:
@143 וּמִנְחַתְהוֹן סוּלְתָּא דְפִילָא בִמְשַׁח תְּלָתָא עִשְׂרוֹנִין לְתוֹרָא חָד לִתְלַת עֲשַׂר תּוֹרִין תְּרֵין עִשְׂרוֹנִין לְדִכְרָא חָד לִתְרֵין דִכְרִין:
@144 וְעִשְׂרוֹנָא עִשְׂרוֹנָא לְאִימְרָא חָד לְאַרְבְּעָא עֲשַׂר אִימְרִין:
@145 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@146 וּבְיוֹמָא תִנְיָנָא תּוֹרִין בְּנֵי תוֹרֵי תְּרֵי עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@147 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@148 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכֵּיהוֹן:
@149 וּבְיוֹמָא תְּלִיתָאָה תּוֹרִין חָד עֲשַׂר דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@150 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִמְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@151 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@152 וּבְיוֹמָא רְבִיעָאָה תּוֹרִין עַשְׂרָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@153 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@154 וּצְפִיר בַּר עִזִין חָד חַטָאתָא בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכַּהּ:
@155 וּבְיוֹמָא חֲמִישָׁאָה תּוֹרִין תְּשַׁע דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@156 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@157 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@158 וּבְיוֹמָא שְׁתִיתָאָה תּוֹרִין תְּמַנְיָא דִכְרִין תְּרֵין אִמְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@159 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@160 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתַהּ וְנִסְכָּהָא:
@161 וּבְיוֹמָא שְׁבִיעָאָה תּוֹרִין שַׁבְעָא דִכְרִין תְּרֵין אִימְרִין בְּנֵי שְׁנָא אַרְבְּעָא עֲשַׂר שַׁלְמִין:
@162 וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרִין לְדִכְרִין וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי לְהוֹן:
@163 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא מִנְחָתָהּ וְנִסְכָּהּ:
@164 בְּיוֹמָא תְּמִינָאָה כְּנִישִׁין תְּהֵא לְכוֹן כָּל עִבִידַת פּוּלְחַן לָא תַעְבְדוּן:
@165 וּתְקַרְבוּן עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ תּוֹר חָד דְכַר חָד אִמְרִין בְּנֵי שְׁנָא שַׁבְעָא שַׁלְמִין:
@166 מִנְחַתְהוֹן וְנִסְכֵּיהוֹן לְתוֹרָא לְדִכְרָא וּלְאִימְרִין בְּמִנְיָנֵיהוֹן כִּדְחָזֵי:
@167 וּצְפִירָא דְחַטָאתָא חָד בַּר מֵעֲלַת תְּדִירָא וּמִנְחָתַהּ וְנִסְכַּהּ:
@168 אִלֵין תַּעְבְדוּן קֳדָם יְיָ בְּמוֹעֲדֵיכוֹן בַּר מִנִדְרֵיכוֹן וְנִדְבוֹתֵיכוֹן לְעֲלְוַתְכוֹן וּלְמִנְחַתְכוֹן וּלְנִסְכֵּיכוֹן וּלְנִכְסַת קוּדְשֵׁיכוֹן:
@169 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל כְּכֹל דִי פַקֵיד יְיָ יָת משֶׁה: פפפ:

@2 **פנחס בן אלעזר בן אהרן הכהן.** לפי שהיו השבטים מבזים אותו, הראיתם בן פוטי זה שפטם אבי אמו עגלים לעבודה זרה והרג נשיא שבט מישראל, לפיכך בא הכתוב ויחסו אחר אהרן: **בקנאו את קנאתי.** בנקמו את נקמתי, בקצפו את הקצף שהיה לי לקצוף. כל לשון קנאה הוא המתחרה לנקום נקמת דבר, אנפרימנ''ט בלע''ז :
@3 **את בריתי שלום.** שתהא לו לברית שלום, כאדם המחזיק טובה וחנות למי שעשה עמו טובה, אף כאן פרש לו הקדוש ברוך הוא שלומותיו:
@4 **והיתה לו.** בריתי זאת: **ברית כהנת עולם.** שאף על פי שכבר נתנה כהנה לזרעו של אהרן, לא נתנה אלא לאהרן ולבניו, שנמשחו עמו ולתולדותיהם שיולידו אחר המשחתן, אבל פנחס שנלד קודם לכן ולא נמשח, לא בא לכלל כהנה עד כאן. וכן שנינו בזבחים (קא, ב) לא נתכהן פנחס עד שהרגו לזמרי: **לאלהיו.** בשביל אלהיו, כמו (במד' יא) המקנא אתה לי, (זכר' ח) קנאתי לציון, בשביל ציון:
@5 **ושם איש ישראל** וגו' **.** במקום שייחס את הצדיק לשבח יחס את הרשע לגנאי: **נשיא בית אב לשמעני.** לאחד מחמשת בתי אבות שהיו לשבט שמעון. דבר אחר להודיע שבחו של פנחס, שאף על פי שזה היה נשיא, לא מנע את עצמו מלקנא לחלול השם, לכך הודיעך הכתוב מי הואהמכה:
@6 **ושם האשה המכה** וגו' **.** להודיעך שנאתם של מדינים שהפקירו בת מלך לזנות, כדי להחטיא את ישראל: **ראש אמות.** אחד מחמשת (במד' לא) מלכי מדין את אוי ואת רקם ואת צור וגו' , והוא היה חשוב מכלם, שנאמר ראש אמות, ולפי שנהג בזיון בעצמו להפקיר בתו מנאו שלישי: **בית אב.** חמשה בתי אבות היו למדין עיפה ועפר וחנוך ואבידע ואלדעה, וזה היה מלך לאחד מהם:
@8 **צרור.** כמו זכור, שמור, לשון הוה. עליכם לאייב אותם:
@9 **כי צוררים הם לכם** וגו' **על דבר פעור.** שהפקירו בנותיהם לזנות, כדי להטעותכם אחר פעור. ואת מואב לא צוה להשמיד, מפני רות שהיתה עתידה לצאת מהם, כדאמרינן בבבא קמא (לח, ב) :
@11 **ויהי אחרי המגפה** וגו' **.** משל לרועה שנכנסו זאבים לתוך עדרו והרגו בהן והוא מונה אותן לידע מנין הנותרות. דבר אחר כשיצאו ממצרים ונמסרו למשה, נמסר לו במנין, עכשו שקרב למות ולהחזיר צאנו, מחזירם במנין:
@12 **לבית אבתם.** על שבט האב יתיחסו, ולא אחר האם:
@13 **וידבר משה ואלעזר הכהן אתם.** דברו עמם על זאת שצוה המקום למנותם: **לאמר.** אמרו להם צריכים אתם להמנות:
@14 **מבן עשרים שנה ומעלה כאשר צוה** וגו' **.** שיהא מנינם מבן עשרים שנה ומעלה, שנאמר (שמות ל, יג) כל העבר על הפקדים וגו' :
@15 **משפחת החנכי.** לפי שהיו האמות מבזין אותם ואומרים מה אלו מתיחסין על שבטיהם, סבורין הם שלא שלטו המצריים באמותיהם, אם בגופם היו מושלים קל וחומר בנשותיהם, לפיכך הטיל הקדוש ברוך הוא שמו עליהם, ה''א מצד זה ויו''ד מצד זה, לומר, מעיד אני עליהם שהם בני אבותיהם. וזהו הוא שמפורש על ידי דוד (תהלים קכב, ד) שבטי יה עדות לישראל. השם הזה מעיד עליהם לשבטיהם, לפיכך בכלם כתיב החנכי הפלאי, אבל בימנה לא הצרך לומר משפחת הימני, לפי שהשם קבוע בו יו''ד בראש וה''א בסוף:
@19 **אשר הצו.** את ישראל על משה: **בהצתם.** את העם על ה': **הצו.** השיאו את ישראל לריב על משה, לשון הפעילו:
@20 **ויהיו לנס.** לאות ולזכרון (במדבר יז, ה) למען אשר לא יקרב איש זר, לחלוק עוד על הכהנה:
@21 **ובני קרח לא מתו.** הם היו בעצה תחלה, ובשעת המחלוקת הרהרו תשובה בלבם, לפיכך נתבצר להם מקום גבוה בגיהנם וישבו שם:
@23 **לזרח.** הוא צוחר, לשון צוהר. אבל משפחת אהד בטלה, וכן חמשה משבט בנימין, שהרי בעשרה בנים ירד למצרים וכאן לא מנה אלא חמשה, וכן אצבון לגד, הרי שבע משפחות. ומצאתי בגמרא ירושלמית, שכשמת אהרן נסתלקו ענני כבוד ובאו הכנענים להלחם בישראל ונתנו לב לחזור למצרים וחזרו לאחוריהם שמנה מסעות מהר ההר למוסרה, שנאמר (דברים י, ו) ובני ישראל נסעו מבארות בני יעקן מוסרה שם מת אהרן, והלא בהר ההר מת, וממוסרה עד הר ההר שמונה מסעות יש למפרע, אלא שחזרו לאחוריהם ורדפו בני לוי אחריהם להחזירם, והרגו מהם שבע משפחות, ומבני לוי נפלו ארבע משפחות משפחת שמעי ועזיאלי, ומבני יצהר לא נמנו כאן אלא משפחת הקרחי, והרביעית לא ידעתי מה היא. ורבי תנחומא דרש שמתו במגפה בדבר בלעם, אבל לפי החסרון שחסר משבט שמעון במנין זה ממנין הראשון שבמדבר סיני, נראה שכל עשרים וארבעה אלף נפלו משבטו של שמעון:
@26 **לאזני.** אומר אני שזו משפחת אצבון, ואיני יודע למה לא נקראת משפחתו על שמו:
@34 **לישוב.** הוא יוב האמור ביורדי מצרים, כי כל המשפחות נקראו על שם יורדי מצרים. והנלדין משם והלאה לא נקראו המשפחות על שמם, חוץ ממשפחות אפרים ומנשה שנלדו כלם במצרים, וארד ונעמן בני בלע בן בנימין. ומצאתי ביסודו של רבי משה הדרשן שירדה אמן למצרים כשהיתה מעברת מהם, לכך נחלקו למשפחות, כחצרון וחמול, שהיו בני בנים ליהודה, וחבר ומלכיאל שהיו בני בנים של אשר. ואם אגדה היא הרי טוב, ואם לאו, אומר אני, שהיו לבלע בני בנים הרבה, ומשנים הללו ארד ונעמן יצאה מכל אחד משפחה רבה ונקראו תולדות שאר הבנים על שם בלע, ותולדות השנים הללו נקראו על שמם. וכן אני אומר בבני מכיר, שנחלקו לשתי משפחות, אחת נקראת על שמו ואחת נקראת על שם גלעד בנו. חמש משפחות חסרו מבניו של בנימין, כאן נתקימה מקצת נבואת אמו שקראתו בן אוני, בן אנינותי ובפלגש בגבעה נתקימה כלה. זו מצאתי ביסודו של ר' משה הדרשן:
@46 **ואלה בני שותלח** וגו' **.** שאר בני שותלח נקראו תולדותיהם על שם שותלח. ומערן יצאה משפחה רבה ונקראת על שמו. ונחשבו בני שותלח לשתי משפחות. צא וחשוב ותמצא בפרשה זו חמשים ושבע משפחות, ומבני לוי שמונה, הרי ששים וחמש, וזהו שנאמר (דברים ז, ז) כי אתם המעט וגו' , ה''א מעט, חמשה אתם חסרים ממשפחות כל העמים, שהן שבעים, אף זה הבנתי מיסודו של ר' משה הדרשן. אך הצרכתי לפחות ולהוסיף בדבריו:
@48 **לאחירם.** הוא אחי שירד למצרים, ולפי שנקרא על שם יוסף שהיה אחיו ורם ממנו נקרא אחירם:
@49 **לשפופם.** הוא מפים, על שהיה יוסף שפוף בין האמות:
@52 **לשוחם.** הוא חשים:
@56 **ושם בת אשר שרח.** לפי שהיתה קימת בחיים מנאה כאן:
@63 **לאלה תחלק הארץ.** ולא לפחותים מבן עשרים, אף על פי שבאו לכלל עשרים בטרם חלוק הארץ, שהרי שבע שנים כבשו ושבע חלקו, לא נטלו חלק בארץ אלא אלו שש מאות אלף ואלף, ואם היה לאחד מהם ששה בנים, לא נטלו אלא חלק אביהם לבדו:
@64 **לרב תרבה נחלתו.** לשבט שהיה מרבה באכלוסין נתנו חלק רב, ואף על פי שלא היו החלקים שוים, שהרי הכל לפי רבוי השבט חלקו החלקים, לא עשו אלא על ידי גורל, והגורל היה על פי רוח הקדש, כמו שמפורש בבבא בתרא (קכב, א) אלעזר הכהן היה מלבש באורים ותמים, ואומר ברוח הקדש אם שבט פלוני עולה, תחום פלוני עולה עמו. והשבטים היו כתובים בשנים עשר פתקין, ושנים עשר גבולים בשנים עשר פתקין, ובללום בקלפי והנשיא מכניס ידו לתוכה ונוטל שני פתקין, עולה בידו פתק של שם שבטו, ופתק של גבול המפורש לו, והגורל עצמו היה צווח ואומר אני הגורל עליתי לגבול פלוני, לשבט פלוני, שנאמר על פי הגורל, ולא נתחלקה הארץ במדה, לפי שיש גבול משבח מחברו, אלא בשומא, בית כור רע כנגד בית סאה טוב, הכל לפי הדמים:
@65 **לשמות מטות אבתם.** אלו יוצאי מצרים. שנה הכתוב נחלה זו מכל הנחלות שבתורה, שכל הנחלות החיים יורשים את המתים וכאן מתים יורשים את החיים. כיצד, שני אחים מיוצאי מצרים, שהיו להם בנים בבאי הארץ, לזה אחד ולזה שלשה, האחד נטל חלק אחד, והשלשה נטלו שלשה, שנאמר לאלה תחלק הארץ, חזרה נחלתן אצל אבי אביהן וחלקו הכל בשוה. וזהו שנאמר לשמות מטות אבתם ינחלו. שאחר שנטלו הבנים חלקוה לפי האבות שיצאו ממצרים, ואלו מתחלה חלקוה למנין יוצאי מצרים לא היו נוטלין אלו הארבעה, אלא שני חלקים, עכשו נטלו ארבעה חלקים: **אך בגורל.** יצאו יהושע וכלב, וכן הוא אומר (שופ' א) ויתנו לכלב את חברון כאשר דבר משה, ואומר (יהושע יט) על פי ה' נתנו לו את העיר אשר שאל: **מטות אבתם.** יצאו גרים ועבדים:
@66 **על פי הגורל.** הגורל היה מדבר, כמו שפרשתי, מגיד שנתחלקה ברוח הקדש, לכך נאמר על פי ה':
@68 **אלה משפחת לוי.** חסר כאן משפחות השמעי והעזיאלי וקצת מן היצהרי:
@69 **אשר ילדה אתה ללוי במצרים.** לידתה במצרים ואין הורתה במצרים. כשנכנסו לתוך החומה ילדתה, והיא השלימה מנין שבעים, שהרי בפרטן אי אתה מוצא אלא ששים ותשע:
@72 **כי לא התפקדו בתוך בני ישראל.** להיות נמנין בני עשרים שנה, ומה טעם: **כי לא נתן להם נחלה.** והנמנין מבן עשרים שנה היו בני נחלה, שנאמר איש לפי פקדיו יתן נחלתו:
@74 **ובאלה לא היה איש** וגו' **.** אבל על הנשים לא נגזרה גזרת המרגלים, לפי שהן היו מחבבות את הארץ. האנשים אומרים (במדבר יד, ד) נתנה ראש ונשובה מצרימה, והנשים אומרות (במד' כז) תנה לנו אחזה. לכך נסמכה פרשת בנות צלפחד לכאן:
@76 **למשפחת מנשה בן יוסף.** למה נאמר, והלא כבר נאמר בן מנשה, אלא לומר לך יוסף חבב את הארץ, שנאמר (בראשית נ, כה) והעליתם את עצמתי וגו' , ובנותיו חבבו את הארץ, שנאמר (במדבר כז, ד) תנה לנו אחזה. וללמדך שהיו כלם צדיקים, שכל מי שמעשיו ומעשה אבותיו סתומים ופרט לך הכתוב באחד מהם ליחסו לשבח, הרי זה צדיק בן צדיק. ואם יחסו לגנאי כגון (מלכים ב' כה, כה) בא ישמעאל בן נתניה בן אלישמע, בידוע שכל הנזכרים עמו רשעים היו: **מחלה נעה** וגו' **.** ולהלן הוא אומר (במדבר לו, יא) ותהיינה מחלה תרצה, מגיד שכלן שקולות זו כזו, לפיכך שנה את סדרן:
@77 **לפני משה ולפני אלעזר.** מגיד שלא עמדו לפניהם אלא בשנת הארבעים, אחר שמת אהרן: **לפני משה.** ואחר כך לפני אלעזר, אפשר אם משה לא ידע אלעזר יודע, אלא סרס המקרא ודרשהו, דברי רבי יאשיה. אבא חנן משום רבי אלעזר אומר בבית המדרש היו יושבים, ועמדו לפני כלם:
@78 **והוא לא היה** וגו' **.** לפי שהיו באות לומר בחטאו מת, נזקקו לומר לא בחטא מתלוננים ולא בעדת קרח שהצו על הקדוש ברוך הוא, אלא בחטאו לבדו מת, ולא החטיא את אחרים עמו. ר' עקיבא אומר מקושש עצים היה. ור' שמעון אומר מן המעפילים היה:
@79 **למה יגרע שם אבינו.** אנו במקום בן עומדות, ואם אין הנקבות חשובות זרע, תתיבם אמנו ליבם: **כי אין לו בן.** הא אם היה לו בן לא היו תובעות כלום. מגיד שחכמניות היו:
@80 **ויקרב משה את משפטן.** נתעלמה הלכה ממנו וכאן נפרע על שנטל עטרה לומר (דברים א, יז) והדבר אשר יקשה מכם תקרבון אלי. דבר אחר ראויה היתה פרשה זו להכתב על ידי משה, אלא שזכו בנות צלפחד ונכתבה על ידן:
@82 **כן בנות צלפחד דברת.** כתרגומו יאות, כך כתובה פרשה זו לפני במרום, מגיד שראתה עינן מה שלא ראתה עינו של משה: **כן בנות צלפחד דברת.** יפה תבעו. אשרי אדם שהקדוש ברוך הוא מודה לדבריו: **נתן תתן.** שני חלקים, חלק אביהן, שהיה מיוצאי מצרים, וחלקו עם אחיו בנכסי חפר: **והעברת.** לשון עברה הוא במי שאינו מניח בן לירשו. דבר אחר על שם שהבת מעברת נחלה משבט לשבט שבנה ובעלה יורשין אותה. שלא תסוב נחלה לא נצטוה אלא לאותו הדור בלבד וכן והעברתם את נחלתו לבתו, בכלן הוא אומר ונתתם, ובבת הוא אומר והעברתם:
@86 **לשארו הקרב אליו ממשפחתו.** ואין משפחה קרויה אלא משפחת האב:
@87 **עלה אל הר העברים.** למה נסמכה לכאן, כיון שאמר הקדוש ברוך הוא נתן תתן להם, אמר אותי צוה המקום להנחיל, שמא התרה הגזרה ואכנס לארץ. אמר לו הקדוש ברוך הוא גזרתי במקומה עומדת. דבר אחר כיון שנכנס משה לנחלת בני גד ובני ראובן שמח ואמר כמדמה שהתר לי נדרי, משל למלך שגזר על בנו שלא יכנס לפתח פלטין שלו, נכנס לשער והוא אחריו, לחצר והוא אחריו, לטרקלין והוא אחריו, כיון שבא לכנס לקיטון, אמר לו בני מכאן ואלך אתה אסור לכנס:
@88 **כאשר נאסף אהרן אחיך.** מכאן שנתאוה משה למיתתו של אהרן. דבר אחר אין אתה טוב ממנו, (דברים לב, נא) על אשר לא קדשתם, הא אם קדשתם אותי עדין לא הגיע זמנכם להפטר. בכל מקום שכתב מיתתם כתב סרחונם, לפי שנגזרה גזרה על דור המדבר למות במדבר בעון שלא האמינו, לכך בקש משה שיכתב סרחונו, שלא יאמרו אף הוא מן הממרים היה. משל לשתי נשים שלוקות בבית דין אחת קלקלה ואחת אכלה פגי שביעית וכו' , אף כאן בכל מקום שהזכיר מיתתן הזכיר סרחונם, להודיע שלא היתה בהם אלא זו בלבד:
@89 **הם מי מריבת קדש.** הם לבדם אין בהם עון אחר. דבר אחר הם שהמרו במרה, הם היו שהמרו בים סוף, הם עצמם שהמרו במדבר צין:
@90 **וידבר משה אל ה'** וגו' **.** להודיע שבחן של צדיקים שכשנפטרין מן העולם מניחין צרכן ועוסקין בצרכי צבור: **לאמר.** אמר לו השיבני אם אתה ממנה להם פרנס אם לאו:
@91 **יפקד ה'.** כיון ששמע משה שאמר לו המקום תן נחלת צלפחד לבנותיו אמר הגיע שעה שאתבע צרכי שיירשו בני את גדלתי. אמר לו הקדוש ברוך הוא לא כך עלתה במחשבה לפני, כדאי הוא יהושע לטול שכר שמושו שלא מש מתוך האהל. וזהו שאמר שלמה (משלי כז, יח) נצר תאנה יאכל פריה: **אלהי הרוחת.** למה נאמר, אמר לפניו: רבונו של עולם, גלוי וידוע לפניך דעתו של כל אחד ואחד ואינן דומין זה לזה, מנה עליהם מנהיג שיהא סובל כל אחד ואחד לפי דעתו:
@92 **אשר יצא לפניהם.** לא כדרך מלכי האמות שיושבים בבתיהם ומשלחין את חילותיהם למלחמה, אלא כמו שעשיתי אני שנלחמתי בסיחון ועוג, שנאמר אל תירא אתו. (במדבר כא, לד) וכדרך שעשה יהושע, שנאמר (יהושע ה, יג) וילך יהושע אליו ויאמר לו הלנו אתה וגו' . וכן בדוד הוא אומר (ש''א יח, טז) כי הוא יוצא ובא לפניהם, יוצא בראש ונכנס בראש: **ואשר יוציאם.** בזכיותיו: **ואשר יביאם.** בזכיותיו. דבר אחר ואשר יביאם שלא תעשה לו כדרך שאתה עושה לי, שאיני מכניסן לארץ:
@93 **קח לך.** קחנו בדברים אשריך שזכית להנהיג בניו של מקום: **לך.** את שבדוק לך את זה אתה מכיר: **אשר רוח בו.** כאשר שאלת שיוכל להלוך כנגד רוחו של כל אחד ואחד: **וסמכת את ידך עליו.** תן לו מתרגמן שידרוש בחייך, שלא יאמרו עליו, לא היה לו להרים ראש בימי משה:
@94 **וצויתה אתו.** על ישראל, דע שטרחנין הם סרבנים הם, על מנת שתקבל עליך:
@95 **ונתתה מהודך עליו.** זה קרון עור פנים: **מהודך.** ולא כל הודך נמצינו למדין פני משה כחמה פני יהושע כלבנה: **למען ישמעו כל עדת בני ישראל.** שיהיו נוהגין בו כבוד ויראה כדרך שנוהגין בך:
@96 **ולפני אלעזר הכהן יעמד.** הרי שאלתך ששאלת שאין הכבוד הזה זז מבית אביך, שאף יהושע יהא צריך לאלעזר: **ושאל לו.** כשיצטרך לצאת למלחמה: **על פיו.** של אלעזר: **וכל העדה.** סנהדרין:
@97 **ויקח את יהושע.** לקחו בדברים והודיעו מתן שכר פרנסי ישראל לעולם הבא:
@98 **ויסמך את ידיו עליו.** בעין יפה יותר ויותר ממה שנצטוה. שהקדוש ברוך הוא אמר לו וסמכת את ידך, והוא עשה בשתי ידיו, ועשאו ככלי מלא וגדוש ומלאו חכמתו בעין יפה: **כאשר דבר ה'.** אף לענין ההוד נתן מהודו עליו:
@100 **צו את בני ישראל.** מה אמור למעלה (כז, טז) יפקד ה'. אמר לו הקדוש ברוך הוא עד שאתה מצוני על בני, צוה את בני עלי. משל לבת מלך שהיתה נפטרת מן העולם והיתה מפקדת לבעלה על בניה וכו' , כדאיתא בספרי: **קרבני.** זה הדם: **לחמי.** אלו אמורין, וכן הוא אומר (ויקרא ג, טז) והקטירם הכהן המזבחה לחם אשה: **לאשי.** הנתנין לאשי מזבחי: **תשמרו.** שיהיו כהנים ולוים וישראלים עומדין על גביו מכאן למדו ותקנו מעמדות: **במועדו.** בכל יום הוא מועד התמידים:
@101 **ואמרת להם.** אזהרה לבית דין: **שנים ליום.** כפשוטו ועיקרו בא ללמד שיהיו נשחטין כנגד היום, תמיד של שחר במערב ושלבין הערבים במזרחן של טבעות:
@102 **את הכבש אחד.** אף על פי שכבר נאמר בפרשת ואתה תצוה, וזה אשר תעשה וגו' (שמות כט, לח) , היא היתה אזהרה לימי המלואים, וכאן צוה לדורות:
@103 **סלת למנחה.** מנחת נסכים:
@104 **העשיה בהר סיני.** כאותן שנעשו בימי המלואים. דבר אחר העשיה בהר סיני, הקיש עולת תמיד לעולת הר סיני אותה שנתקרבה לפני מתן תורה שכתוב בה (שמות כד, ו) וישם באגנות מלמד שטעונה כלי:
@105 **ונסכו.** יין: **בקדש הסך.** על המזבח יתנסכו: **נסך שכר.** יין המשכר פרט ליין מגתו:
@106 **ריח ניחח.** נחת רוח לפני שאמרתי ונעשה רצוני:
@108 **עלת שבת בשבתו.** ולא עולת שבת זו בשבת אחרת, הרי שלא הקריב בשבת זו שומע אני יקריב שתים לשבת הבאה, תלמוד לומר בשבתו, מגיד שאם עבר יומו בטל קרבנו: **על עלת התמיד.** אלו מוספין, לבד אותן שני כבשים של עולת התמיד. ומגיד שאין קרבין אלא בין שני התמידין, וכן בכל המוספין נאמר על עולת התמיד לתלמוד זה:
@110 **ושלשה עשרונים.** כמשפט נסכי פר, שכן הן קצובין בפרשת נסכים:
@112 **זאת עלת חדש בחדשו.** שאם עבר יומו בטל קרבנו ושוב אין לו תשלומין:
@113 **ושעיר עזים** וגו' **.** כל שעירי המוספין באין לכפר על טמאת מקדש וקדשיו, הכל כמו שמפורש במס' שבועות (דף ט, א) . ונשתנה שעיר ראש חדש שנאמר בו לה', ללמדך שמכפר על שאין בו ידיעה לא בתחלה ולא בסוף, שאין מכיר בחטא אלא הקדוש ברוך הוא בלבד, ושאר השעירין למדין ממנו. ומדרשו באגדה אמר הקדוש ברוך הוא, הביאו כפרה עלי על שמעטתי את הירח: **על עלת התמיד יעשה.** כל הקרבן הזה: **ונסכו.** אין ונסכו מוסב על השעיר, שאין נסכים לחטאת:
@116 **כל מלאכת עבדה.** אפלו מלאכה הצריכה לכם, כגון דבר האבד המתרת בחלו של מועד אסורה ביום טוב:
@117 **פרים.** כנגד אברהם, שנאמר (בראשית יח, ז) ואל הבקר רץ אברהם: **ואיל.** כנגד אילו של יצחק: **כבשים.** כנגד יעקב שנאמר (בראשית ל, מ) והכשבים הפריד יעקב. ביסודו של רבי משה הדרשן ראיתי זאת:
@122 **כאלה תעשו ליום.** שלא יהיו פוחתין והולכין כפרי החג:
@124 **וביום הבכורים.** חג השבועות קרוי בכורי קציר חטים על שם שתי הלחם, שהם ראשונים למנחת חטים הבאים מן החדש:
@129 **תמימים יהיו לכם ונסכיהם.** אף הנסכים יהיו תמימים. למדו רבותינו מכאן שהיין שהעלה קמחין פסול לנסכים:
@135 **מלבד עלת החדש.** מוספי ראש חדש שהוא ביום ראש השנה:
@140 **מלבד חטאת הכפרים.** שעיר הנעשה בפנים האמור באחרי מות, שגם הוא חטאת: **ועלת התמיד.** ומלבד עולת התמיד תעשו עולות הללו: **ונסכיהם.** מוסב על המוספין הכתובים ועל תעשו והוא לשון צווי מלבד עולת התמיד ומנחתה תעשו את אלה ונסכיהם. וכן כל ונסכיהם האמורים בכל המועדות חוץ משל קרבנות החג שכל ונסכה ונסכיהם ונסכיה שבהם מוסבים על התמיד ואינן לשון צווי, שהרי נסכיהם של מוספין כתובין לעצמן בכל יום ויום:
@147 **ומנחתם ונסכיהם לפרים.** פרי החג שבעים הם. כנגד שבעים אמות שמתמעטים והולכים, סימן כליה להם, ובימי המקדש היו מגינין עליהם מן היסורין: **ולכבשים.** כנגד ישראל שנקראו (ירמיה נ, יז) שה פזורה, והם קבועים ומנינם תשעים ושמונה לכלות מהם תשעים ושמונה קללות שבמשנה תורה. בשני נאמר ונסכיהם על שני תמידי היום ולא שנה הלשון אלא לדרוש, כמו שאמרו רבותינו זכרונם לברכה בשני ונסכיהם, בששי ונסכיה, בשביעי כמשפטם, מ''ם יו''ד מ''ם, הרי כאן מים, רמז לנסוך המים מן התורה בחג:
@164 **עצרת תהיה לכם.** עצורים בעשית מלאכה. דבר אחר עצרת עצרו מלצאת, מלמד שטעון לינה. ומדרשו באגדה לפי שכל ימות הרגל הקריבו כנגד שבעים אמות וכשבאין ללכת, אמר להם המקום בבקשה מכם עשו לי סעודה קטנה כדי שאהנה מכם:
@165 **פר אחד איל אחד.** אלו כנגד ישראל, התעכבו לי מעט עוד. ולשון חבה הוא זה, כבנים הנפטרים מאביהם והוא אומר להם קשה עלי פרידתכם עכבו עוד יום אחד. משל למלך שעשה סעודה וכו', כדאיתא במסכת סכה (דף נה, ב) ובמדרש רבי תנחומא למדה תורה דרך ארץ, שמי שיש לו אכסנאי יום ראשון יאכילו פטומות, למחר מאכילו דגים, למחר מאכילו בשר בהמה, למחר מאכילו קטניות, למחר מאכילו ירק, פוחת והולך כפרי החג:
@168 **אלה תעשו לה' במועדיכם.** דבר הקצוב לחובה: **לבד מנדריכם.** אם באתם לדור קרבנות ברגל, מצוה היא בידכם או נדרים או נדבות שנדרתם כל השנה תקריבום ברגל, שמא יקשה לו לחזור ולעלות לירושלים ולהקריב נדריו, ונמצא עובר בבל תאחר:
@169 **ויאמר משה אל בני ישראל.** להפסיק הענין, דברי רבי ישמעאל, לפי שעד כאן דבריו של מקום ופרשת נדרים מתחלת בדבורו של משה, הצרך להפסיק תחלה ולומר שחזר משה ואמר פרשה זו לישראל, שאם לא כן יש במשמע שלא אמר להם זו אלא בפרשת נדרים התחיל דבריו:
@170 **ויד ה'.** ( תרגום: ) רוח גבורה מן קדם ה' נתלבש כח לרוץ לפני המרכבה ברגליו, שלא ילך אחאב יחידי, שחלק כבוד למלכות ( מכילתא, ילקוט שמעוני רמז ריז ): **וישנס מתניו.** כמו ויאזור, ואין לו דמיון, ואף הוא לא בא אלא ללמד לשון זירוז, נזדרז כגבור:
@172 **כה יעשון אלהים.** כמו שעשית לנביאי הבעל:
@174 **רותם.** ייניבר"א בלע"ז: **ויאמר רב.** ( תרגום: ) סגי לי ארכא, עד אימתי אנא מטריף כדין:
@176 **רצפים.** פחמים, וכן ( ישעיהו ו ו ): ובידו רצפה:
@179 **אל המערה.** היא נקרת צור ( שמות לג כב ) שעמד בה משה ( ראה מגילה יט ב ):
@180 **את מזבחותיך הרסו.** במות יחיד הנעשות לשם שמים, שהרי מזבח בית הבחירה בירושלים היה:
@181 **ורוח גדולה.** ( תרגום: ) משרית מלאכי רוחא: **ברעש.** ( תרגום: ) משרית מלאכי זיעא:
@182 **אש.** ( תרגום: ) משרית מלאכי אשתא: **קול דממה דקה.** ( תרגום: ) קל דמשבחין בחשאי, אבל בנביאי אומות העולם אומר ( איוב ד טז ): **דממה וקול אשמע, דממה היתה לשבח.** ואני שמעתי קול הבא מתוך הדממה, דטינטישמנ"ט בלע"ז, ואין שומעין הקול ממש:
@183 **וילט פניו.** ( תרגום: ) וכריך אפוהי, וכן הוא אומר ( שמואל א כא י ): לוטה בשמלה:
@186 **תמשח לנביא תחתיך.** אי איפשי בנביאותך, מאחר שאתה מלמד קטיגוריא על בני:
@187 **ימית אלישע.** לא מצינו שהמית אלא ארבעים ושנים ילדים על ידי הדובים ביריחו ( מלכים ב ב כד ):
@190 **לך שוב.** מאחרי: **כי מה עשיתי לך.** שתבא אחרי:
@191 **בשלם הבשר.** בשל להם את הבשר, כך פירשו דונ"ש ומנחם, וכן תרגמו יונתן בשתי תיבות ( בשיל להון ). ואני אומר, אין צריך לחלקו לשתי תיבות, ומהו בשלם הבשר, בשלם לשני השוורים את הבשר שלהם, שהצמד אין פחות משנים: **ויתן לעם.** מרוב שמחה עשה משתה. ( ה ) כי שלחתי אליך וגו' לי תתן. ידעתי כי תתנם לי, אבל אחרת אני גוזר עליך:

@3 **את בריתי שלום.** ר"ל שכמו ששם שלום בין ישראל ובין השם יתעלה כן יהיה לו בריצת שלום והיתה לו ולזרעו אחריו ברית כהונת עולם. ר"ל שלא תפסק הכהונה ממנו ומזרעו לעולם וזאת הברכה היא להשאיר זרעו תמיד שבזולת זה לא תהיה בכאן ברכה כי כל הבאים מזרע אהרן הם כהנים ואפשר שרמז זה לכהונה גדולה הוא היותר נכון ואמר שתהיה לו להבטיחו שלא ימות קודם אלעזר אביו ויהיה הוא כהן גדול אחרי אביו וזרעו אחריו יהיו כהנים גדולים לא תפסק זאת הכהונה מהם והנה ידענו כי פינחס היה כהן גדול ומזרעו היו כהנים גדולים רבים כמו שנתבאר בספר דברי הימים ואין לספק על זה ממה שמצאנו שהיו כהנים גדולים מבני איתמר וזה כי אלו היעודים הכוללים ומקיפים בכל הזמן יש בהם תנאי בהכרח ולזה אפשר שסר זה היעוד עת מה בסור התנאי כמו שסרה קצת המלכו' מזרע שלמה בן דוד בסור התנאי:
@4 **תחת אשר קנא לאלהיו.** ושמר ישראל מהכליון יהיה לו ברית שלום ותחת אשר כפר על בני ישראל נתן לו ולזרעו שיהיה מכפר על בני ישראל ולזה נתן לו כהנה גדולה כי הכהן הגדול יכפר על בני ישראל פעם אחת בשנה כמו שהתבאר בפרשת אחרי מות.
@5 והנה זכר שהאיש המוכה היה נשיא שבט שמעון והאשה המוכה היתה בת מלך ממלכי מדין כי צור היה שם אחד מהמלכים באמרו את אוי ואת רקם ואת צור להורות על חזק קנאת פנחס לשם יתעלה עד ששם נפשו בכפו להרוג נשיא שבט אחד ובת מלך:
@8 **צרור את המדינים וגו' כי צוררים הם לכם.** צוה השם יתעלה שישנאו ישראל את המדיינים ויכו אותם לפי שהם היו שונאים את ישראל במחשבתם הרעה שהשתדלו להכשיל את ישראל בבנותיהן ובע"ז כדי שיכלם השם יתעלה וזה היה בעצת בלעם עד שכבר נמשכו לזה כלם וגם המלכים אשר שם הפקירו בנותיהם לישראל להכשילם כמו שנתבאר בדברי כזבי ועתה נוספה שנאתם בעבור כזבי שנהרגה שהיתה בת מלך א' ממלכי מדין. ולזה הוא מבואר שאם לא תמהרו להכותם ישתדלו בצדדים אחרים להזיק לישראל ועוד שזאת המלחמה תשלם ע"י משה באופן יותר שלם לכלות את המדינים ממה שיעשה ע"י יהושע לחזק ההבדל שבין משה ליהושע ולזה תמצא בזאת המלחמה מהפלא מה שלא ימצא כמוהו במלחמה אחת ממלחמו' יהושע כי בעם ממעט נצחו תכף עם גדול ורב לא החיו כל נשמה מהזכרים והיו באופן מהרבוי שהיה מספר הנקבות מהטף אשר לא ידעו משכב זכר ל"ב אלף ועם כל זה לא נפקד איש מאנשי המלחמה אשר באו שם ולזה רצה הש' יתע' שתעשה זאת המלחמה קודם שיאסף משה אל עמיו וזה ממה שיורה על עוצם העונש שנענשו ישראל כשלא היתה להם הארץ ירושה ע"י משה רבינו כמו שזכרנו במה שקדם:
@11 **ויהי אחרי המגפה וגומ'.** רצה השם יתעלה שימנו ישראל אחר המגפה מבן עשרים שנה ומעלה לפי שרצה לצוות ע"י משה רבינו איך תחלק הארץ באופן שלא יתחדש אחריו מחלוקת בזה ולזה מנאם והגביל שלאלה הנמנים תחלק הארץ והם הראויים לצאת לצבא והנה נבאר איך יהיה זה במה שיבא בג"ה:
@11 **ויאמר ה' אל משה ואל אלעזר וגו'.** אמר השם יתעלה זה למשה שיאמר אותו לאלעזר והנה היה אלעזר לפה משה במקום אהרן אביו:
@13 **וידבר משה ואלעזר הכהן אום.** הוא כמו עמם וכמוהו דברו לשלום כמו שזכר החכם א"ע:
@14 **מבן עשרים שנה ומעלה כאשר צוה ה' את משה.** ר"ל שאמרו להם למנותם מבן עשרים שנה ומעלה וכן עשו כאשר צוה יי' את משה והכתוב אחז דרך קצרה להיות זה העניין מובן בעצמו:
@14 **ובני ישראל היוצאים מארץ מצרים.** לפי שלא נגזרה מיתה במדבר על יוצאי מצרים כי אם על אשר היו מבן עשרים שנה ומעלה בשנה השנית לצאתם מארץ מצרים וכבר היו אז שם רבים למט' מעשרי' שנה בא להגיד בזה המקו' של מתו אלה במדבר ולזה היו בספורם בזה המקום רבים שהיו מיוצאי מצרים ולזה אמר שימנום עתה ואין לאומ' שיאמר שלא ימנו עתה כי אם הנשארים מיוצאי מצרים שלא היו בני עשרים שנה במספר האחד כי כבר אמר שאו את ראש כל עדת בני ישראל וגו'. ולזה יחוייב שימנום כלם רוצה לומר מה שהיה מהם מבן עשרים שנה ומעלה ואין צורך עוד להאריך בזה:
@15 והנה הגיע מהתועלת בזה המכפ' להודיע שיותר חסר שבטו של שמעון מכל שאר השבטים שחסר מספרן וזה כי שבט שמעון חסר ל"ז אלף ומאה ושלשים על שאר השבטים שחסר מספרן והם ראובן וגד ואפרים ונפתלי לא חסר ממנו כי אם כ"ג אלף ותשע מאות ועשרים וזה הורה שרוב התלונות אשר היו במדבר היו מהאנשים אשר משבטו של שמעון ולזה נפקדה ברכתו בפרש' וזאת הברכה ולזה גם כן אמר יעקב בסודם אל תבא נפשי ובקהלם אל תחד כבודי להתבאר לו שהם היו קנטרנים והגיע עוד מהתועלת בזה המספר השני להודיע שכבר נתקיימה הברכה שבירך יעקב את יוסף לתת לו שכם אחת על אחיו כי ראובן היה בכור ויוסף בכו' וכבר היה נחלת יוסף יותר מנחלת ראובן כמו נחלת שמעון ויותר מזה כמו שאמר אפרים ומנשה כראובן ושמעון יהיה לי וזה כי אלו שנחלקה להם הארץ תמצא במספרם שכבר היה מספר מנשה ואפרים יותר ממספר ראובן ושמעון וזה כי מספר ראובן ושמעון לא היה כי אם שישים וחמשה אל ותשע מאות ושלשים ומספר מנשה ואפרים היו חמשה ושמונים אלף ומאתים ולא היה כן העניין במספר הראשון שנזכר בפרשת מדבר סיני וזה שמספר ראובן ושמעון היה אז מאה אלף וחמשים אלף ושמונה מאות ומספר מנשה ואפרים לא היה אז כי אם ע"ב אלף ות"ש והנה זכר שם בנות צלפחד בעבור מה שספר מענינם אחר זה בענין דיני הנחלות והנה הסכים בקרוב זה המספר השני למספר הראשון לא חסר כי אם אלף ושמונה מאות ועשרים:
@19 **הוא דתן ואבירם קרואי העדה אשר הצו על משה ועל אהרן וגו'.** למדנו בזה שהם היו בזאת המריבה והמחלקת כמו התחלה ושרש יותר מקרח ולזה אמ' ותבלע אותם ואת קרח להעיר שהם היו הסבה הראשונה והם סבבו השחתת החמשים ומאתים איש ואולם הקדים קרח בפרש' קרח למעלתו ולזה תמצא שדתן ואבירם מתו הם וכל אשר להן ואין העניין כן בקרח כי בניו לא מתו כמו שספר בזאת הפרש' והער שמהם היו משוררי' רבים בימי דוד וידמה שהם היו במקום בעינו שהיה קרח כשפתחה הארץ את פיה ונתבצר ונתחזק המקום אשר תחת כפות רגליהם בדרך שלא בלעה אותם הארץ לזה הוצרך לומר ובני קרח לא מתו כי היו במקום שהיו ראויים מות ולזה אמרו רז"ל מקום נתבצר להם בגיהנם כי המקומות הנפתחי' בזה האופן שנפתחה הארץ בעת היותה פתוחה יקראו גיהנם או גיא בן הנום:
@20 **ויהיו לנס.** רוצה לומר שהיו לאות ולזכרון לבני ישראל להזהירם שלא יקרב איש אשר לא מזרע אהרן הוא לעבודת המקדש.
@63 **לאלה תחלק הארץ.** ר"ל לאלו הנמנים והנה לא זכר פקודי לוי כי אם אחר המאמר הזה כי כבר ביאר במה שקדם כי שבט לוי לא ינחל נחלה בתוך בני ישראל ולזה אמר לאלה להוציא שבט לוי ולהוציא הגרים והעבדים כי אלו לא נמנים כי לא היו מתיחסים לאחד מהשבטים והנמנים היו מיחסים בכללם לשבטים כמו שנתבאר מהדברים אשר בזה המספר:
@63 **במספר שמות.** לא רצתה התורה שימנו הם בעצם אבל ימנו שמותיהם כמו שנזכר בפרשת במדבר סיני וכבר נתבארה הסבה בפרשת כי תשא ובזה האופן גם כן מנאום בזה המקום ואם לא נזכר:
@64 **לרב תרבה נחלתו ולמעט תמעיט נחלתו וגו'.** ירצה לפי מה שאחשוב שכאשר יחלקו בני השבט ביניהם נחלת שבט יותן ממנו לאיש ולאיש לפי פקודיו ואין הרצון שלא ינחלו עמהם הקטנים מכ' שנה שלא נמנו עמהם כי זה דבר בלתי ראוי אך תהיה הנחלה מגעת לאיש מחלק השבט לפי יחס פקודי ביתו לפקודי כל השבט ואחר זה תהיה זאת הנחלה מתחלקת בין כל בני הבית הקטנים מכ' שנה ואש מעשרי' שנה ומעלה כאלו היתה להם זאת הנחלה מאביהם ולזה אמרו רז"ל שהמתי' היו יורשים החיים בזאת הנחלה ולפי שאמר איש לפי פקודיו למדנו שהנקבות אינם נוחלות אבל ינחל האיש ולזה באו בנות צלפחד להתרעם על זה העניין לפני משה:
@65 **אך בגורל יחלק הארץ.** להורות שהחלוקה ההיא גם כן תהיה ע"פ הגורל ואין טענת מנחלת כלב ויהושע שלא היו בגורל לפי שהם היו ע"פ יי' כמו שנזכר שם וענין הגורל אינו כי אם לבאר שזה המוגבל מהשם יתעלה כמו שאמר בחוק יוטל את הגורל ומיי' כל משפטו:
@65 **אך בגורל יחלק הארץ וגו'.** למדנו מזה כי החלוקה שנתחלקה הארץ תחלה לשבטים היתה ע"פ הגורל וכן מצאנו בספר יהושע ויש לשאול איך יתכן שתהיה זאת החלוקה ע"פ הגורל והנה אין החלקים שוים ואם אמרנו שחלקוה תחלה לחלקים שוים ע"פ הגורל לדעת באי זה מקום שתהי' נחלת השבט וכאר ידעו באיזה מקום תהיה נחלת השבט הוסיפו עליהם אם היה רב מספרו או מעט ממנ' אם היה מעט הנה יתחייב מזה שיהיה אפשר שתסור מהשבט כל הנחלה לו בגורל והמשל שאם היה בא הגורל מיששכר ויהודה ודן וזבולון זה אצל זה הנה יכנס כל הגורל החמישי בנחלתן לפי שמספרן היה יותר משליש מספר כל ישראל יותר מחצית ששית שהוא חלק שבט אחד ולזה ידמה שהיה זה כשחקרו על פי הגורל בחלק מה מהארץ לאי זה שבט יהיה והמשיכו לו שם מהארץ לפי הראוי לו לפי פקודי השבט לצדדים אשר ידעום ע"פ הגורל ואחר זה הפילו גורל השני במה שנמשך לנחלת אותו המטה לדעת אי זה שבט ינחילנו והמשיכו לו ג"כ שם ע"פ הגורל הראוי לו לפי פקודי השבט ההוא ולזה אמר בספר יהושע ויהי הגורל הראשון ומה שאמר שם שיחלקו הארץ לשבע' חלקים לא היה שיפילו הגורל בין השבטים הנשארים בחלקי' ההם כי זה יהיה בלתי אפשר אם לא ידעו בתחלה למי יהיה כל חלק וחלק מהם בדרך שיחלקו זה לפי פקודי כל שבט אבל היה העניין להודיע כל חלקי הארץ ההיא כדי שיוכלו להשות החלוקה לפי פקודיהם על פי הגורל ולזה הביאו עמם זכרון הערים אשר בכל חלק וחלק ועמדו על יחסם ויחס קצתם אל קצת ואחר כך חלקוה בגורלות זה אחר זה באופן שזכרנו ולזה כתוב גם כן ויהי הגורל כך:
@66 **על פי הגורל תחלק נחלתו בין רב למעט.** ר"ל שנחלת המטה גם כן חלק בין בני המטה בגורל ולזה גם כן אמר אחר אמרו איש לפי פקודיו יותן נחלתו:
@69 **אשר ילדה אותה ללוי במצרים.** זה אינו מחויי' שלא תהיה הורתה גם כן במצרים כמו שלא יחייב אמרו ויולד ליוסף בארץ מצרים:
@72 **ויהיו פקודיהם שלשה ועשרים אלף כל זכר מבן חדש ומעלה.** מזה המקום יש קצת ראיה כי המתים במדבר לא מתו בזולת עתם ולזה הגביל השם יתע' זמן כלותם עד מ' שנה ולו היה רוצה להמיתם בלא עתם היה ממית אותם במעט זמן אלא שלא היה ענשם דבר דמות כי סופם היה למות גם כן אבל היה ענשם מיתם במדבר שנתעכבו שם ישראל בעבור זה עד מ' שנה ולזאת הסבה תמצא שפקודי בני לוי לא הוסיפו על פקודיהם במספר הראשון כי אם שבע מאות ואף על פי שלא נגזר עליהם שימותו פקודיהם במדבר ובני ישראל עם מות פקודיהם במדבר היה המספר השני מסכים בקרוב למספר הראשון ואין טענה על זה מיהושע וכלב שהיו מן האנשים ההם אשר אפשר שיורה שהשאר מתו על צד העונש וזה כי הם היו מהמרגלים אשר נגזר עליהם שימותו תכף במגפה לפני יי' וכמו שנגזר על אלו שימותו בלא עתם על צד העונש מצד הדבה שהוציאו על הארץ כן נתן השם יתעלה ליהושע וכלב ארך חיים בעבור שלא הסכימו עם המרגלים ונפרדו מעצתם ואפשר שנאמר שקצת מתי מדבר מתו כלא עתם אלא שמעטי המספר היו ולזה האריך השם יתעלה זמן עמידתם במדבר מ' שנה כדי שיהיו על המעט ארש מתו בסוף זה הזמן כמו בני ס' בקרוב:
@78 **אבינו מת במדבר והוא לא היה וגו'.** חשבו שאם היה שם היה ראוי שיענש שלא יהיה מזרעו חלק ונחלה בארץ:
@78 **כי בחטאו מת ובנים לא היו לו.** ר"ל שחטאו היה סבה שמת בלא בנים כי כל עונש ראוי שייוחס אל החטא:
@79 **למה יגרע שם אבינו מתוך משפחתו כי אין לו בן וגו'.** לפי שהמתים היו יורשים החיים בזאת הירושה כמו שזכרנו אמרו כן כי לא היו בזרע צלפחד פקודים וזה יהיה סבה אל שיגרע שמו מתוך משפחתו בזאת הנחלה אם לא תשוב הירושה לאבי אביהן ולזה שאלו להם שתשוב הירושה לאבי אביהן כדרך שתהיינה יורשות ירושת אביהן:
@82 **כן בנות צלפחד דוברות.** דבר ראוי וצודק הן אומרות:
@82 **נתון תתן להם אחוזת נחלה בתוך אחי אביהן.** כאלו אחי אביהן ואביהן יורשים אבי אביהן והוא חפר אלא שזאת הירושה תהיה לאחי אביהן ואביהם לפי הפקודים אשר בהם בזה המספר אשר נמנו בערבו' מואב ואח"כ יחלקו הנחלה ביניהן כראוי לפי מה שזכרנו:
@83 **ואל בני ישראל תדבר לאמר איש כי ימות ובן אין לו וגו'.** לפי שהתחיל על דבר בנות צלפחד לבאר קצת דיני הנחלה רצה להשלים ביאורם וביאר בז שאם שם בן קודם לבת ולזה לא תהיה הבת יורשת בין האחים אך אם אין שם בן הנה תהיה הבת יורשת נחלת אביהן ואם אין לו בת חזרה הנחלה לאביו ולזה מחלקין אותה אחיו מאביו ביניהם וכבר יתבאר שלא תבא הירוש' לאחיו מאמו מאמרו אחר זה לאחי אביו מורה שכבר דקדק שיהיה מהאב ואמר גם כן שאם אין אחים לאביו תנתן נחלתו ליותר קרוב אליו מאביו ממשפחתו ולזה לא יאמר כי אם על משפחת האב כי משפחת האב קרויה לבדה משפחה אמר למשפחותם לבית אבותם ולזה תמצא כי בכל המשפחות שזכרה התורה זכר לבד המשפחות המסתעפות מהאב ואל האב ייחס תמיד שם המשפחה:
@85 **ואם אין לו אחים ונתת' את נחלתו לאחיו אביו.** וזה כי הירושה תשוב לאבי האב וממנו תהיה לבניו הראויים לירשו:
@86 **ואם אין אחים לאביו ונתתם את נחלתו וגו'.** הנה הירושה תשוב לאבי אבי האב וירשו זאת הירושה כל הראויים לירשו וכן בזה הדרך יעלה ממדרג' אחר מדרגה בדרך שתהיה הירושה ליותר קרוב לו ממשפחתו ומזה יתבאר שכמו שהבן יורש האב כן האב יורש את הבן ואם אי אפשר שתשוב הירושה לאב כי אין לו יורש וכבר מת הנה תשוב הירושה לאבי האב וירשו זאת הירושה כל הראויים לירשו כן ימשך בזה הדרך עניין הנחלה לשוב לאבי אבי האב או למעלה ממנו עד שתגיע לקרוב אליו ממשפחתו וראוי שיתבאר מזה שאם שבה הירושה דרך משל לבן בן הבנות ומת בלא יורש חזרה הירושה לאביו וממנו תשוב לבנותיו שהם אחיות המת כי אין לו בן אך אם נשאר לו אח הה תהיה הירושה לאח כמו שנזכר בזה המקו' ואולם אם תירש האם את הבן אם לא הנה יתבאר מזה המקום שאין האם יורשת הבן שאם היתה האם יורשת את הבן הנה ראוי שתשוב הנחלה לאחיו מאמו אם אין לו אחים מאביו והתורה דקדקה בהפך זה ר"ל שלא תצא הנחלה ממשפחת אביו ולזה אמר שאם אין לו אחים תשוב הנחלה לאחי אביו ואול' אם ירש הבן את אמו אם לא הנה זה ממה שיתבאר בג"ה בסוף פרשת אלה מסעי והנה לא נתבאר מן התורה אם הבעל יורש את אשתו אם לא אבל חכמי' תקנו שיהיה הבעל יורש את אשתו:
@89 **כאשר מריתם פי וגומ'.** הנה המרי היה שלא הקדישו השם יתעלה במים לעיני העדה לפי שהם הבינו ממה שאמר להם השם יתעלה ודברתם אל הסלע בזולת כונה שכיון בו השם יתעלה והיה זה סבה אל שלא יקדישוהו במים ההם באופן שהיה רצון השם יתעלה בו:
@91 **יפקוד יי' אלהי הרוחות לכל בשר וגו'.** לפי שהיה שואל ממנו דבר הוא מיוחס אל ההשגחה הפרטית והיא תהיה מצד השכל קראו אלהי הרוחות לכל בשר ר"ל מנהיג הנפשות אשר לכל אחד מהאנשים והנה שאל ממנו שיתן לישראל מנהיג ורועה יצא לפניהם במלחמה ויבא לפניהם ויוציאם כשירצה ויביאם בדרך שתהיה הנהגתם שלמה ויהיו כלם בהסכמה אחת ולא תהיה עדת השם יתעלה כצאן אשר אין להן רועה והנה צוה לו השם יתעלה שיקח את יהושע בן נון וישימהו רועה אל העם:
@93 **איש אשר רוח בו.** ר"ל רוח אלהים כי הוא היה ראוי לנבואה:
@93 **וסמכת את ידך עליו.** להעיר שאליו תתן הגדולה והשררה שיש לך כמו שיסמוך האדם על קרבן להעיר שעליו נתן את חטאיו:
@94 **והעמדת אותו לפני אלעזר הכהן ולפני כל העדה.** כדי שיתפרסם להם שאתה מקים אותו להיות במקומך ולזה גם כן צוהו השם יתעלה שיצוה את יהושע לעיניהם איך יתנהג בהנהגה הזאת:
@95 **ונתת מהדך וגומר.** ר"ל מיופי תכונותיך ועניניך בהנהגה והודם להגיע בה הטוב למונהגים ביותר שלם שאפשר:
@95 **למען ישמעו כל עדת בני ישראל.** ר"ל הנה תצוה אותו לעיניהם ותתן מהודך עליו גם כן לעיני העדה למען ישמעו כל עדת בני ישראל אל דבריו מפני ידיעתם שאתה הקמות אותו תחתך והנה לפני אלעזר יעמד ר"ל על דבר הגדת העתידות:
@96 **ושאל לו במשפט האורי' לפני יי'.** הנה הוצרך לזה יהושע לפי שלא היה כחו בנבואה ככח משה רבינו ע"ה שתגיע לו הנבואה בהקיץ בכל מה שירצה ולזה היה צריך אל שיעזר בשאלותיו באורים ותומים על ידי אלעזר שהיה כהן גדול והיה נושא החשן והאפוד לפני יי' ר"ל אצל בית קדשי הקדשים:
@96 **על פיו יצאו ועל פיו יבאו.** ר"ל על פי יהושע יצאו ויבאו אע"פ שהוא שואל העתידות לאלעזר במשפט האורים והוא מה ששאל משה אשר יוציאם ואשר יביאם:
@96 **הוא וכל בני ישראל אתו.** הוא מה ששאל משה אשר יצא לפניהם ואשר יבא לפניהם כי הוא יצא או יבא וכל בני ישראל יהיו אתו בדרך שיצא לפניהם ויבא לפניהם ובצאתו ובבאו יהיו כל בני ישראל אתו וכל העדה יצאו ויבאו על פיו אף על פי שלא יצא ויבא לפניה' או יהיה הרצון באמרו וכל העדה סנהדרי גדולה כי הם נקראו עדה כמו שביארנו באמרו ואם כל עדת ישראל ישגו או יהיה הרצון באמרו הוא וכל בני ישראל אתו שאלעזר הכהן יצא גם כן על פי יהושע ויבא וכל בני ישראל אתו וכל העדה שהם הסנהדרין כולם יצאו ויבאו ע"פ יהושע כי לו נתנה ההנהגה בזה ואף על פי שהוא שואל במשפט האורים לאלעזר או יהיה אמרו וכל העדה שב לעדה מיוחדת שבישראל שאם יצוה לה לצאת ולבא יחויב לה לשמוע בקולו ואף על פי שלא יצוה זה לכל ישראל והמשל שאם רצ לשלח במלחמה אלף או אלפים או כמה שירצה יחוייבו בם לשמוע בקולו והנה עשה משה כאשר צוהו השם יתע'. ולא היתה עינו צרה בתת שררתו ליהושע בן נון. זה ביאור דברי זאת הפרשה הצריכים אל ביאור.
@100 **צו את בני ישראל ואמרת אליהם את קרבני לחמי וגומר.** לפי שלא הקריבו במדבר עולות כמו שאמר עולת תמיד העשויה בהר סיני הוצרך להזכיר עתה שנית דבר או הקרבנות ועוד כי מפני שהיו הקרבנות מוכנים ומכוונים להגיע הנבואה בצד שיהיה הכהן יותר ראוי אל שיגיד העתידות כשישאלוהו במשפט האורים כמו שביארנו במה שקדם והיו עתה ישראל מאד צריכים אל זה לפי שנבואת משה עומדת לפסק ונבואת יהושע לא תספיק לפי שנבואת יהושע לא תספיק אם לא יעזר לשאלות במשפט האורים לאלעזר הכהן הנה הוצרך להזכיר את דבר הקרבנות ואמר צו את בני ישראל ואמרת אליהם וגו'. להעיר שעליהם המצוה הזאת אעפ"י שהיתה נעשית על יד הכהנים וזה עדות שאלו הקרבנות אשר זכר בזה המקום הם באים משל צבור ואמר את קרבני לחמי כי הלחם הוא הבשר היה כלו קרב לשם יתעלה כי היתה העולה כלה כליל ואמר לאשי ר"ל לקרבני ואמר זה בלשון רבים לפי ששני התמידין אשר היו קרבים ביום אחד הם יחד מעירים בדבר נפלא לא יעיד בה אחד מהן ביחוד כמן ושביארנו בפרשת אתה תצוה ולזה יצטרך בכל יום לפי שהיו זריזים על זה בשניהם ואמרו במועדו הוא להזהיר שיקרבום בכל יום בזמנו הקצוב לכל אחד מהן והוא גם כן ראיה שאפילו בשב יקריבוהו אלא שכבר נתבאר זה בביאור במה שאמר וביום השב שני כבשים וגו'. על עולת התמיד ונסכה והנה ביארנו זאת המצוה בפרשת ואתה תצוה:
@104 **עולת תמיד העשויה בהר סיני.** אמר זה לפי שלא הקריבו עולה במדבר זולתי בהר סיני כמו שכתב החכ' א"ע:
@105 **בקדש הסך נסך שכר לה'.** למדנו מזה המקום שנסוך היין לא יהיה מן היין החדש ולזה אמר שכר שהוא יין ישן ושיערו חכמים כי עד ארבעים יום הוא פסול לעניין זה. ואמנ' אחר זה נקרא שכר כי כבר נתבררו שמריו וזה הביאור הוא מצד הוראת הגדר והנה אמר שיהיה זה הנסוך בקדש להורות שלא יהיה הנסוך הזה במזבח על המערכ' אשר יערכו עליה אברי התמיד עם שהוא מבואר גם כן בצד אחר כי התורה הזהירה שלא לכבות אש המערכה ולזה היה הנסוך בזה המקום כמו שביארנו בפרשת תצוה ובפרשת שלח לך כי התורה ידמה שכונה בה להסיר העפוש והלכלוך מהבית הקדוש ההוא:
@107 **וביום השבת שני כבשי בני שנה תמימים.** הנה דין הקרבתם כדין התמידין בשוה אין הבדל ביניהם אלא שלא יבאו עמהם שני גזירי עצים כי זה לא חייבה התורה אלא בתמיד של שחר ושל בין הערבים כמו שנתב' בפרשת וירא ובפרשת צו ולא חייבה זה בהקרבנות שביניהם כמו שביארנו והנה המוספין היו קרבים בין תמיד של שחר ושל בין הערבי' כי לא היה שם קרבן קרב קודם תמיד של שחר ולא אחר תמיד של בין הערבים כמו שביארנו שם עול' שבת בשבתו למדנו מזה שאם שכחו או נאנסו ולא הקריב עולת שבת זו אי אפשר להם שיקריבו ביום אחר או בשב אחר אך בשבתו לבד:
@108 **על עולת התמיד ונסכה.** זה מרה שעולת התמיד קרבה ראשונה קודם המוספין והנה דבר הנסכין התבאר בפרשת שלח לך:
@109 **ובראשי חדשיכם תקריבו עולה לה' פרים בני בקר שנים וגומ'.** אלו העשר עולות היה מוסיף בראש חדש עם נסכיהם הראוי להם לפי מה שנתבאר בפרשת שלח לך ומעשיהם במעשה התמידי אלא שהם קרבים בין שני התמידין כמו שזכרנו מוסף של שבת:
@112 **זאת עולת חדש בחדשו לחדשי השנה.** מגיד שבכל ר"ח יקריבו כך מן העולות יותר על התמידין ומגיד גם כן שאם לא הקריבם ביום ההוא אין להם תשלומין לא בר"ח ולא יום אחר:
@113 **ושעיר עזים אחת לחטאת לה' על עולת התמיד יעשה ונסכו.** מגיד שאחר עולת התמיד היה מקריב החטאת לפי שהחטאת קודם לעולת כמו שביארנו במה שקדם ואחר כך היה מקריב עולות המוסף והנה מצאנו כי ההשעיר היה בא בצבור לכפר על טומאת מקדש וקדשיו כשעיר הנשחט של יום הכפורים שהיה חטאת. ומצאנו גם כן בשעירי הרגלים שנאמר בהם ושעיר עזים אחד חטאת לכפר עליהם ולזה למדנו שכלם באים לכפר על הטמאה ומהם נלמד ששעיר של ר"ח בא גם כן לכפר על הטמאה והו' מבואר שיחוייב מזה ששעירי הרגלי' מכפרים מהטומאה מה שלא יוכל שעיר ר"ל לכפר ולזה יצטרך ג"כ להקריב שניהם בר"ח ושעיר של יום הכפורי' מכפר מהטומאה מה שלא יוכלו שעירי הרגלים לכפר. והנה הוצרכה התורה אל זה לפי שכבר סדרה התורה לסוג מה משגגת טומאת מקדש וקדשיו קרבן עולה ויורד כמו שביארנו בפרשת ויקרא ולפי שנשארו שם סוגים אחרים לא יכפר עליהם זה הקרבן הנה סדרה התורה אלו החטאות של צבור לכפר על הטומאות ההם בהדרגה והנה אחשוב שאמר בשעיר של ר"ח לחטאת ליי' ובשעירי הרגלים נאמר ושעיר חטאת אחד לכפר עליכם לפי שהוא בא לכפר על הטמאה שלא היתה בה ידיעה כלל לבעלים והוא ידועה לשם לבדו ולזה אמרו שהוא בא לכפר על קבר התהום שאין בו ידיעה לא בתחלה ולא בסף ובשעירי הרגלים אמר לכפר עליכם כי הוא מכפר על שגגת מקדש וקדשיו שהיתה בה ידיעה מה ושעיר של יום הכיפורים מכפר אפיו על הזדון:
@114 **ובחדש הראשון.** כבר התבאר אופן מעש הפסח בארבעה עשר לחדש ניסן במה שקדם והתבארו גם כן דיני החגיגה ודין אכילת המצות בז ההרגל והמלאכות האסורות בראשון ושביעי של פסח והמותרות והם המלאכות שהם לצורך אוכל נפש ואולם המוסף הנעשה בכל יום מימי הרגל הזה לא נתבאר במה שקדם אך אמר בכללות בפרשת אמור אל הכהנים על דבר המוסף הזה והקרבתם אשה ליי' שבעת ימים ובמקום הזה ביאר עניין זה האשה והוא שוה למוסף ר"ח וזה ממה שיחזק שיהיו אלו השעירים באים על דברי מתיחסים כמו שזכרנו והנה יתבאר ממה שאמר בזה המקום שבעת ימים מצות יאכל שאכילת המצה שבעת ימים רשות אך הרצון בו שמה שיאכל מלחם יהיה מצה ואין שם חיוב באכילת מצה כי אם בלילה הראשונה כמו שביארנו בפרשת בא אל פרעה. וראוי שתדע שמה שהקפידה התורה במניין אלו העולות במוספי' אינו לעכב אך על צד היותר טוב כמו שנבאר בג"ה בזכרון תועלת אלו המוספין. ולזה אם לא מצאו אלא פרים יקריבו פרים לא מצאו אלא איל יקריבו איל לא מצאו אלא בשים יקריבו שבעה כבשים לא מצאו שבעה יקריבו מה שמצאו שנאמר בפרשת אמור אל הכהנים והקרבתם אשה ליי' שבעת ימים לא הקפידה התורה אלא שיקרבו אשה ואמר בזה המקום שבעת ימים לחם אשה ואמר על עולת התמיד יעשה ונסכו מגיד שא לא מצאו אלא אחד מאלו העשרה יקריבוהו וכן אמר במוסף ר"ח ובמסוף השבת נאמר על עולת התמיד ונסכה מגיד אם לא מצאו אלא כבש אחד מקריבים אותו:
@124 **ובים הבכורים בהקריבכם מנחה חדשה ליי'.** למדנו שהיא הראשונה לכל המנחות הבאות מן החדש ואף עלפי שהעומד מתיר את החרש להדיוט לא הותר לגבוה לכתחלה עד הקרבת זאת המנחה אלא שאם הביא לא פסל כיון שקרב העומר שהרי קרא הכתוב מנחת העומר מנחת בכורים בפרשת ויקרא אלא שהוא ראוי שימתינו למנחות הבאות מהחטים עם שתי לחם של עצרת ולזה קראה הכתוב מנחה חדשה:
@129 **תמימים יהיו לכם ונסכיהם.** למדנו מזה שהנסכים צריך שיהיו תמימים. ורואי שתדע שזה המוסף הנזכר בזה המקו' הוא זולת הנזכר בפרשת אמור אל הכהנים כי הוא היה קרב על הלחם כמו שנזכר שם והעד כי שם צוה להקריב פר אחד ואלים שנים ושבעה כבשים בני שנה לעולה ושעיר עזים אחד לחטאת. ובזה המקום צוה שני פרים ואיל אחד ושבע כבשים לעולה ולזה יהיו קרבים ביום הזה לעולה ארבעה עשר כבשים ושלשה פרים ושלשה אלים ושני שעירי עזים לחטאת ולפי שהיו בכאן שני מוספין אמר ונסכיהם וכן העניין במוסף ראש השנה:
@130 **ובחדש השביעי באחד לחדש וגומ'.** כבר התבארו דיני היום הזה במה שקדם לו נתחדש בו בזה המקום אלא המוספין וכבר נתבאר עניין מוסף ראש חדש וכמוהו הוא זה המוסף אלא שבזה המוסף לא יהיה כי אם פר אחד ובמוסף ראש חדש יהיו שני פרים:
@135 **מלבד עולת החדש.** למדנו זה שמוסף ראש חדש קרב קודם מוסף ראש השנה ומזה המקום יש ללמוד כי תדיר ושאינו תדיר תדיר קודם והנה אמר בו בפרשת אמור אל הכהנים והקרבתם אשה ליי' וכן ביום הכפורים ובחג הסכות אמר שם שבעת ימים תקריבו אשה ליי' להגיד שאין זה המספר הנזכר בזה המקום לעכב אלא למצוה ולזה גם כן כתב אלו המוספין בזה המקום ולא זכר אותו במקום אשר זכר הדברים העצמיים באלו הימים להורות שאין זה לעכב אלא למצוה ואולם המעכב הוא מה שנזכר במקומו והוא שיקריבו אשה להשם:
@136 **ובעשורי לחדש השביעי הזה.** כבר נתבארו דיני הנעשה בזה במה שקדם לא נתחדש בו בזה המקום אלא המוסף והוא שוה למוסף ר"ה הנזכר בזה המקום:
@140 **מלבד חטאת הכפורים.** למדנו שחטאת הכפורים קודם לזה ולפי שאמר מלבד חטאת הכפורי' ונזכר בפרשת אחרי מות כבר היה בא עם חטאת הכפורים שיה בא מן הצבור איל אחד לעולה והוא הנקרא שם איל העם למדנו שהאיל ההוא הוא איל הנזכר בזה המקום ולזה לא יקריבו בזה המקום כי אם איל אחד לעולה והוא הנקרא שם איל העם למדנו שהאיל ההוא הוא איל הנזכר בזה המקום ולזה לא יקריבו בזה המקום כי אם איל אחד לעולה לא שני אילים:
@141 **ובחמשה עשר יום לחדש השביעי וגו'.** מצאנו בו בזה חדוש במספר העולות בפרים ובאילים לא בכבשים כי בר"ה ובחג השבועות יעלו גם כן י"ד כבשים אלא ששם היו ג' אילים ובזה המקום ב' אילים ושם היו מהפרים ג' בחג השבועות ובר"ה ב' ובזה המקום מצאנו מהפרים ביום הראשון י"ג ואחר כך מתמעטים והולכים באופן שהיו הפרים ביום שביעי שבע פרים ואולם בשמיני עצרת היה המוסף בשוה כמוספי ר"ה ויום הכפורים הנזכרים בזה המקום והנה נתחדש בכל מוספי חג הסכות שתמצא בהם כמשפטם או כמשפט קודם זכירת החטאת ולזה למדנו מזה שמעשה העולות קודם למעשה החטא כי לא הקפידה התורה בזה בכל אלו הימים לבד ללא ענין ועוד למדנו מזה שמעשה הפרים קודם למעשה האילים ומעשה האילים קודם למעשה הכבשים אף על פי שאינם מעכבים זה את זה כמו שביארנו הנה כשיעשו יעשו בסדר הנזכר בזה המקום:
@168 **לבד מנדריכם.** זה ביאור מה שצריך בזאת הפרשה.

@1 **ואולם התועלות המגיעות מזאת הפרשה הם ח':**
@1 **התועלת** הראשון הוא להודיע כי ה' יתע' ישלם לעושה הטוב בטובתו ולזה היה ברית שלום לפינחס תחת שומו בין ישראל ובין השם ית' והיתה לו הכהונה הגדולה לו ולזרעו לכפר על בני ישראל תחת אשר כפר על ישראל בזה המעשה:
@1 **התועלת** השני הוא להודיע שמי שיתאמת לו מאחר שהוא מבקש לכלותו ראוי שיקדים הוא לכלות האחר להציל עצמו ולא תמצא שצוה השם יתע' להכות המדינים מפני ידיעתו שנאתם אל ישראל ובקשם רעתם עם מה שנוספה השנאה בהריגת כזבי בת צור:
@1 **התועלת** השלישי הוא מה שלמדנו מזה המספר שנמנו ישראל בערבות מואב שכבר נתקיימה ברכת יעקב במה שאמר אפרים ומנשה בראובן ושמעון יהיה לי כמו שביארנו בביאור דברי זאת הפרשה:
@1 **התועלת** הרביעי הוא להודיע שראוי להרחיק המחלוקת תכלית ההרחקה ולזה התחכמה התור' לסדר איך תהיה חלוקת הארץ באופן לא יהיה עמה ערער ומחלוקת. ועשתה זה טרם היות להן הארץ כי אולי אחר זה יאמרו קצתן שטרחו יותר במלחמה או הצליחו יותר בו ויבקשו מפני זה שיהיה להם חלק יותר גדול ויהיה זה סבה לחדוש הקטטה והגבילה גם כן זה בתכלית מה שאפשר מהיושר ר"ל שיקח כל אחד מהנחלה לפי פקודיו אשר יתכן בהם שיצאו לצבא כי הם אנשי המלחמה וראוי שיהיה חלקם חלק כחלק ואחר כך ישוו הנחלה ביניהם באופן שזכרנו כדי שלא יהיו הקטנים אשר לא יצאו לצבא בזולת נחלה:
@1 **התועלת** החמישי הוא להודיע שכבר נתקיים יעוד ה' ית' שימותו כל אנשי המלחמה במדבר זולתי כלב בן יפונה ויהושע בן נון:
@1 **התועלת** הששי הוא להודיע שאין ראוי שימנע האדם מפני הבושת מהביא משפטו לפני הגדולים אבל ראוי שישתדל בזה בחריצות ובזריזות כדי שיגיע לו הראוי הלא תראה כי בנות צלפחד לא בשו מהביא משפטן לפני משה ולפני אלעזר הכהן ולפני הנשיאים וכל העדה עד שהשיגו מבוקשן במה שהיו מבקשות מדב' נחלה לפי שכבר שאלו כהוגן כמו שביאר':
@1 **התועלת** השביעי הוא במצו' והוא מה שצוו לדון בדיני נחלות לפי מה שזכרה התורה והנה לא היתה הבת יורשת כי מדרכה שתהיה נקנית לא קונה אלא אם יהיה זה בזה המקום שאין שם בן כי אז ראוי שתהיה הבת יורשת אביה כדי שלא יעזוב לאחרים חילו והנה לא תשוב הנחלה לאחים מן האם כדי שלא תסוב נחלה ממשפחה למשפחה ולזה הוא ראוי שתשאר לבני המשפחה היותר קרובים וכבר נעמוד על היותר קרובים כשנעלה העניין אל האב ואחר אל אבי האב ואחר אל אבי אבי האב כמו שביארנו:
@1 **התועלת** השמיני הוא להודיע שהוא ראוי למנהיג השלם שישתדל בשלום המונהגים ממנו גם בעת העדרו מהם לפי מה שאפשר ולזה מצאנו שכאשר הביא ההכרה שיאסף משה אל עמיו השתדל עם השם יתעלה שיפקוד איש על העדה אשר יוציאם ואשר יביאם ויסדר ענין קבוציהן כדי שלא יהיו כצאן אשר אין להם רועה כי זה יהיה סבה לבלבול עניניהם ושמע השם יתעלה לקולו ונתן על העדה יהושע בן נון אשר למדו משה והכינו ושמחו בגבול מהשלמות שהיה ראוי לנבואה וצוהו משה והישירהו על מה שיעשה ואיך תהיה הנהגתו באופן שלא יחסר בה דבר ממה שיהיה בו תועלת לעם:
@168 **ואולם התועלות המגיעות ממנה הם י':**
@168 **התועלת** הראשן הוא להודיע שיש בהקרבת העולות תועלות בהגעת הנבואה ולזה סמך דבר הקרבת העלה למה שזכר מורך הנביא לשאל במשפט האורים לכהן גדל כמו שזכרנו:
@168 **התועלת** השני הוא במצות והוא לזרז ישראל על מצות התמידים לפי שלא הקריבום במדבר זולתי בהר סיני וכבר זכרנו התועלת המיוחד המגיע מהקרבת התמידים בפר' ואתה תצוה ובספר ויקרא ביארנו התועלת המגיע מהקרבת העולה באופן שזכרה אותו התורה:
@168 **התועלת** השלישי הוא במצות והוא מה שצותה התורה להוסיף על התמידין בשבת שני כבשים בני שנה תמימה רוצה לומר שלא יוסיפו על שנה ויהיו בלי מום:
@168 **התועלת** הרביעי הוא במצות והוא מה שצותה התורה להקריב קרבן מוסף בר"ה והוא שני פרי' ואיל אחד ושבעה כבשים בני שנה תמימים לעולה ושעיר עזים אחד לחטאת:
@168 **התועלת** החמישי הוא במצות והוא מה שצונו להקריב מוסף בחג המצות והוא שני פרים ואיל אחד ושבעה כבשים בני שנה תמימים לעולה ושעיר עזים אחד לחטאת:
@168 **התועלת** הששי הוא במצות והוא מה שצונו להקריב מוסף בחג השבועות והנה העולות שיקריבו זה היום הם עשרם עשר על הלחם ועשר לחובת היום יתר על התמידים:
@168 **התועלת** השביעי הוא במצות והוא מה שצונו להקריב מוסף בר"ה על מוסף ר"ח והנה העולות שיקריבו ביום הזה יתר על התמידים הם י"ט עשר למוסף ר"ח ותשע למוסף ר"ה:
@168 **התועלת** השמיני הוא במצות והוא מה שצונו להקריב מוסף ביום הכפורים והנה העולות שיקריבו יתר על התמידים הם תשעה:
@168 **התועלת** התשיעי הוא במצות והוא מה שצונו להקריב קרבן מוסף ביי חג הסכות ואולם המוספים מתחלפים במספר העולות כי פרי החג הם מתמעטין והולכי' לפי רבוי הימים:
@168 **התועלת** העשירי הוא במצו' והוא מה שצונו להקריב קרבן מוסף בשמיני עצרת הנה מספר העולות הקרבות בו הם תשע ואולם התועלת המגיע בהיות המוספין על זה האופן הנזכר פה הנה זה יתבאר כשנציע תחלה קצת דברים ביארנום בה' מספר מ"י וזכרנום במה שקדם מביאורנו זה והוא כי המכוון מהקרבנות הוא להעיר על מציאות הצורה וכ"ש העולות וכן העניין במועדים אלא שהם יעירו על מציאות הצור' הראשונה כמו שביארנו במה שקדם ונאמ' כי הוא מבואר כי בצד מה תהיה הצורה השביעי במדרגה הוא ה' ית' והם צורות היסודו' ואחריה צורת הדומם ואחריה צורת הצומח ואחריה צורת המרגיש ואחריה צורת המדבר ואחריה צורת השכלי' הנפרדי' העלולי' והשביעית הוא האלוה ית' ובצד אחר יותר בורר המדרגו' כאלו תהיה הצורה השמיני' היא ה' ית' וזה שכבר תהיה הצורה הששית מניע הגלגלי' שכל אחד מהם ישיג באופן מה חלק מנימוס הנמצאות וסדרם וישרם כמו שביארנו בה' ממ"י והצורה השביעית השכל הנאצל מהגרמי' השמימיי' והוא בצד מה משיג כללות נימוס הנמצאו' השפלות ויש לו השגה מה בעליונות כמו שביארנו בה' ממ"י ומצד אחר יותר בורר המדרגות האלו תהיה הצורה התשיעי' הוא ' ית' וזה שכבר תהיה הצורה השישית מניעי גלגלי כוכבי לכת והצורה השביעית הוא המגיע לערבות כי הוא עליון מאד על אלו המניעי' ובאופן מה תקיף השגתו בהשגות כלם כמו שביארנו בחמישי ממ"י אלא שהשגת השכל הפועל בנימוס מה שיתחייב מכל אלו המגיעים היא יותר שלמה מהשגת זה המגיע כמו שביארנו שם והנה בצד אחר ימנו בו אלו המניעים הנבדלי' והוא יותר מיוחד מהקודם שיהיה ה' ית' הוא העשירי ויהיו ז' מניעי לז' כוכבת לכת והשמיני מניע גלגל הכוכבים הקיימים והתשיעי הוא השכל הפועל והעשירי הוא השם יתע' ובצד אחר יותר בורר מזה הקודם יהיה השם ית' הוא החמישים כשימנו כל מניעי הגלגלים והראשיי' והמשרתי' להם וכבר ביארנו שהענין הוא כן במופת שאין ספק באמתתו בה' ממ"י ושאם התבאר כי לכל אחד מכוכבי לכת גלגל אחד יניעהו התנועה היומית וגלגל אחר מיוחד יניעהו התנועה המתאחרת וזה ממה שזכרנו אותו על דרך ההצעה לבאר ממנו סבת כל הנזכר באלו המוספין ונאמר שהנראה לנו במוסף שבת שנכפלו בו העולות הקרבות בכל יום הוא מפני מה שיעיר עניין קדושת היום השביעי על מציאות הש"י וההשגה בו מצד מה שנעמוד על זאת המדרגה השביעית מהצורות שהיא הש"י נבדל לעבודת הש"י להעמידנו על זאת הפנה ולפי שמזה הד נכפלה ההכנה להגעת הנבואה לכהן הוכנו בו עוד מהעולות שנים להעיר על מה שראוי שתכפל השגה וההכנה ביום זה להתיחדו לעבודת הש"י ולזה ראוי שישלם בו יותר מתבודדות השכל מבין שאר הכוחות הנפשיות ולהתמיד יותר זה ההתבודדות כדי שישלם ביום הזה וזה שכיון בו וכפלו אלו העולות ואולם מוסף ראש חדש היה ביום ההוא אשר בו חדוש ראיית הלבנה כי חדושו יורה על תנועת הגרמים השמימיים בעצמם כי זה מורה שאין השמי' קיימים והארץ מתנועעת התנועה היומית כמו שחשבו אנשי' וזה שאם היה הדבר כן היה הירח מתמיד במרחק אחד מהשמש ואנחנו רואים הפך זה כי בכל חדש תשיג הירח השמש פעם אחת ואחר תרחק ממנו מעט מעט עוד תשוב להתקרב אליו מעט מעט וכן העניין באור הירח שהוא מוסיף תחלה מעט מטע ועד יחסר אורה מעט מעט עד שיעדר ואחר ישוב להראות ואז הוא חדוש הלבנה וזה ממה שיחייב בהכרח שיהיו השמי' מתנועעי' ולפי שהוא מבואר שיחוייב בכל מתנועע שיהיה לו מניע הנה יחוייב שיהיה לגרמי' השמימיי' מניע ולזה נעמוד על מציאות הצורות הנבדלות ולפי שכאשר יעוין בהם בזה האופן ימצאו בהכרח שבעה מניעים לכוכבי לכת ומניע אחד לגלגל ערבות ושכל אחד כמו משותף ושופע מכלם והוא השכל הפועל והשכל אשר הוא ההתחלה הראשונה לכל נמצאו' היה שם מספר העולות עשר להעמיד על מציאות ההתחלה הראשונה שלא יטעה אחד כשיחשב כי המניע לגלגל ערבות הוא הש"י כמו שחשבו זה קצת גדולי הפילוסופים כי אין העניין כן כמו שביארנו במה שאין ספק בו באמתתו בה' ממ"י ולזה היו שם שבעה כבשי' להעיר על מניעי גלגלי שבעה כוכבי לכת ואיל אחד שהוא יותר שלם מהכבש להעיר על מניע גלגל ערבות שהוא יותר נכבד מאד ממניעי שבעה כוכבי לכת והיו שם שני פרים להעיר על מציאות השכל הפועל ומציאות הש"י ואע"פ שהם מתחלפי המדרגה מאד לאין שיעור הנה מפני קצת שיתוף שיתדמה ביניהם שתפם והנה השתוף ההוא הוא כי אצל השכל הפועל ימצא הנימוס המושכל לכל הנמצאות השפלות ומן הענין בשם ית' אלא שאצלו ימצא הנימוס המושכל לכל הנמצאות במוחלט כמו שביארנו בה' ממ"י ומצד השתוף הזה טעה אלישע אחר וחשב שיהיה השכל הפועל הוא השם יתע' וזה אמרם ז"ל מטטרון חזא ששמו כשם רבו ולהסיר מזה העטות סדרה התורה בזה המוסף ב' פרים להעמידנו על מציאות הסבה הראשונה והנה לבאר ההבדל בין השם ית' ובין השכל הפועל תמצא בקצת המקומות שלא שם בו כי אם פר אחד להעיר על מציאות הש"י ושם בו ב' אלים להעיר על מניע ערבות ועל השכל הפועל מצד שתוף מה ביניהם כי מניע ערבות אצלו ציור כולל הרבה מציורי מניעי כוכבי לכת כמו שביארנו בה' ממ"י ולזה היה אצלו מציור נימוס הנמצאו' השפלות וסדרם וישרם קרוב למה שימצא מזה לשכל הפועל ולפי שהמכוון בטומאת מת הוא להעמיד על מציאות הצורה כמו שקדם והיה בכאן מה שיעמיד באופן שלם על מציאות הצורה הנה מן הראוי היה שיהיה נכלל בזדה מה שיכפר על הטומאה ולזה היו בכאן שעירי עזים לחטאת לכפר על הטומאה והא כולל לשעירי הרגלים ג"כ ובזה ג"כ תשלם הסבה במה שנזכר במוסף הפסח כי הוא מסכי' למה שנזכ' במוסף ראש חדש בשוה והנה היה נעשה בט"ו לחדש כי אז תהיה הלבנה בתכלית המרחק מהשמש ויהיה אורה שלם ויורה עניינ' מפני זה על תנועת השמי' כמו שהורה עליו חדושה וסור אורה ולזאת הסבה ג"כ היה חג הסכות בט"ו יום לחדש והנה היו מספר ימי החג שבעה להורות מצד הימים על מציאות ה' ית' כשנעמוד מהצורה על שבע מדרגותיהם אשר השביעית הוא ה' ית' ולפי שבבחינת עצמם תהיה הראשונה ה' ית' הנה היום הראשון קדש לפי שבבחינת עמידתינו עליהם תהיה האחרונה השם ית' היה היום השביעי שבתון ואולם במוסף חג השבועות נכפלה ההערה הזאת במה שקרב על הלחם ובמסוף היום והיום בעצמו מעיר על המניע החמשים שהוא ה' ית' ולזה היה היום החמשים קדש ולפי שלא יגיע מספר המניעי' לזה המספר אם נניח שלא יהיה לתנועה היומית כי אם גלגל אחד ושאין לתנועה המתאחרת ג"כ כי אם גלגל אח' כמו שחשבו אנשים הנה הישירתנו התור' בזה ההכפל שיש שם שבעה מניעים מסכימים בכוכבי לכת בכל אחד מאלו התנועות ולזה היו בכאן שבעה כבשי' שני פעמים וכבר בארנו במופת אמיתי שהעניין הוא כן בה' ממ"י ולפי שהיה זה להעיר על החמישי' שהוא קדש לא היה החג כי אם יום אחד ואמנם החדש השביעי הנה קדושו מורה על המדרגה השביעית שהוא קדש לפי שהוא שביעי לחדשי' ולפי שהוא ידריך בקדושת היום להעיר על שהעשירי קדש ולזה היה היום העשירי מזה החדש קדש גם כן הנה במוסף היום לא העיר במדרגת הצורו' כי אם על תשע והיה הפר מורה על השכל הפועל והאיל מורה על מניע ערבות והכבשים השבעה על מניעי הגרמים השמימיי' והנה היה היום הראשון קדש לפי שה' ית' הוא הצורה הראשונה בבחינת עצמו הצורות והיה היום העשירי קדש לפי שהשם יתע' הוא הצורה המושגת לנו באחרונ' והנה קדושת היו' הראשון מורה על שהעשירי קדש וט' העולות מורות על ט' הצורות הנשארו' וכן הענין בקדושת היום העשירי ולזה לא היו בו כי אם ט' עולות והנה לא שם הצורה העשירי' במספר העולות להורו' על רוממות ה' ית' על אלו הצורות ולזאת הסבה ג"כ לא היתה שם קדושה נוספת בימי' שבין הראשון והעשירי להורות על עוצם ההבדל שיש בין ה' ית' ובין אלו השכלי' העלולים ממנו ואפשר ג"כ שנאמר שהתשע עולות מורות על תשע מדרגות מהצורו' והתשיעי קדש באופן שזכרנו בהצעה ויהיה הפר להעיר על ה' ית' אלא שהדרך הראשון הוא היותר נכון מצד הסכמת שבעת כבשי' זה לזה במשל והוא מבוא' לפי מה שזכרנו מהתועלת במועדם אשר התחלתם הוא חג המצות ומעיר על התחלת התישר האדם לדעות האמיתיות ולזה ג"כ היה לחמו מצה וחג הביכורים מורה על התישרות יותר ולזה היו בו מתן תורה והיו שתי הלחם בו חמץ והחדש השביעי מעיר על תכלית ההתישרות והוא מבואר כי בהתחלת ההשגה לא ישיג האדם מאד ההבדל בין הש' ית' ובין השכל הפועל ולזה הושמו' העולו' עשר בחג המצות ובחג השבועות ג"כ ואולם אחר התכלית ההשגה יושג מאד ההבדל בזה ולזה לא הושמו העולות בראש השנה וביום הכיפורי' כי אם תשע להפלגת ההבדל הנראה אז בין המדרגה אשר לשם יתעלה ובין מדרגת השכלים העלולים ממנו ולזה הושם המעיר על השם יתעלה יום קדוש והמעיר על שאר השכלים תשע עולות ולפי שזאת ההשגה תתוסף תמיד לא היה ההבדל חזק בין אחד לחדש השביעי ובין שאר הימים שיש בינו ובין העשירי כחזק ההבדל בין היום העשירי לחדש השביעי ובין שאר הימים האלו וזה כי היום העשירי אסור בעשיית כל מלאכה ובו פרישות מכל התענוגים הגופיים וזה כי כל מה שיתחכם האד יותר יכיר יותר עוצם ההבדל בין השם יתעלה ובין שאר הצורות ולזאת הסבה תמצא שבחג הסכות שהיו שבעת ימים להורות על שהצורה הראשונה מאלו המדרגות השבעה מהצורות הוא קדש והוא הש"י הושם היום הראשון קדש כי הוא הצורה הראשונה מצד עוצם מדרג הצורות ולא חששה התורה להשים היום השביעי קדש מפני היותו מאוחר בידיעה לפי שאחר שלמות האדם באלו ההשגות יצוייר בעצם ציורו שהש"י הוא הראשון והנה היה יום אחד לחדש השביעי יום תרועה להעיר האנשים שיקיצו משנת התרדמה ויעיינו בזה עד שיעמדו על אמתת מה שכוונה התורה בזה וכן היה ביום הכפורים בשנת היובל לזאת הסבה כי קדוש היובל יעמוד על קדוש המדרגה החמשי' ועשירי לחדש על קדוש העשיר והנה היו ארבעה עשר כבשים במוספי חג הסכות לסבה שזכרנו בעולות חג השבועות והיו שם שני אלים להורות על שבערבות ג"כ שני מניעי' האחד מניע התנועה היומית והאחר מניע התנועה המתאחרת ושהם זולת המניעים אשר באלו התנועות לאחד אחד מכוכבי לכת והם יותר שלמים מהם לסבות האחד מצד שהם משרתים בכוכבי לכת ואולם בערבות האחד מהם ראשון והשני מצד רוממות הנימוס המסור' מערבות על הנימוס המסודר מאחד אח' מכוכבי לכת וזה כלו ממה שהתבאר באור שלם בה' ממ"י ואולם הפרים כשחוברו באלו הימים היו תמיד י"ד והנה היו שם תמיד שבעה פרים והם מעירים על המניעים הראשיים והם מניעי הגלגל אשר בו כוכב כוכב מכוכבי לכת ולהעיר שהם יותר נכבדות מהשאר היו פרי' העולות המעירים עליהן והנכלל בפרי' הנשארים והימים שהיו תמיד שבעה מורים על מניעים אחרים נעמוד עליהם מצד תנועת החלוף הנמצאת לכל אחד מהם כי זה דבר משותף לכל כוכבי לכת ר"ל שימצא להם תנועת האורך מיוחדת ותנועת חלוף תשימה בלתי שוה והנה כשנתבונן באלו החלופים בכללם נעמוד על מספר המניעים כמו שיתבאר לך מדברינו בה' ממ"י והנה לחלוף עניניהם הושמו המעירים עליהם ימים ופרים ואפשר עוד שנאמר כי הפרים שנוספו בכל יום על שבעה העירו על דברים יעמידונו בצד יותר מיוחד על מספר המניעי' אשר לכוכבי לכת והנה יהיה מה שהורו עליו הששה פרים הנוספים לפי זאת ההנחה זולת מה שהורו עליו החמשה פרים הנוספים ביום השני וזולת מה שהורו עליו הארבעה פרים הנוספים ביום השלישי וזולת מה שהורה עליו השלשה פרים הנוספים ביום הרביעי וזולת מה שהורה עליו השני פרים הנוספים ביום החמישי וזולת מה שהורה עליו הפר הנוסף ביו' השישי ר"ל מה שיעיר עליו הנעשה ביום אחד מהם היה זולת מה שיעיר עליו הנעשה ביום אחר והוא מבואר כי אחר התנועות שהיו מהמניעים הראשיים לכוכבי לכת ימצאו שם תנועות משותפות לששה לבד מכוכבי לכת והוא תנועת החלוף כי היא לכלם זולת השמש ותנועות משותפות לחמשה מהם והוא היות תנועת הרוחב בהם בלתי קיימת ברוחב אחד והנזורות והיושר והעמידה כי היא לכלם זולת השמש והירח ותנועות משותפות לד' מאלו הה' הנבוכי' והוא תנועת הארך המיוחדת שתהיה בגובה בסבוב האחד מפעם אחת ותנועות משותפות לשלשה מהם והוא היות הגזורות בעת נגודם לשמש והיושר בעת היותם עמו כי זה ימצא לשבתאי וצדק ומאדים לבד ותנועות משותפות לשנים מהם והוא היות הככב בגובה בסבוב האחד ב' פעמים כי זה יהיה לירח ולכוכב לבד ובצד האחד יהיה לשנים מהם לבד הגזורות בהיותם עם השמש והנה נוגה וכוכב תנועה לא תמצא כי אם לאחד מהם והוא הרחב הקוים הנמצא לירח וכאשר נתבונן באלו התנועות ובמשיגיהם יתאמת לנו מספר המניעים כמו שביארנו בחמישי מספר מלחמות השם ולזה היו אלו הפרים מתמעטים והולכי' כאלו הישירתנו התורה בזה האופן לעמוד על מספר אלו המניעים כדי שנעמוד על מציאות החמשי' שהוא קדש והוא הש"י והנה היה השמיני עצרת רגל בפני עצמו לפי שאם היה שתהיה הוראתו על שהשמיני הוא קדש רוצה לומר ממדרגו' הצורות כמו שהצענו הנה הורה זה היחוד ליום היה מבין שאר הימים עד שהוא רגל בפני עצמו הבדל זאת המדרגה משאר המדרגות עם שבזה האופן יתישר יותר להיות היום הזה מורה על העשירי שהוא קדש במה שיעלו בו במוסף תשע עולות המורות על שבעה כוכבי לכת ומניע ערבו' והשכל הפועל לפי מדרגותיהם כמו שזכרנו ולזה הבדיל מהם המורה על מציאות העשירי שהוא קדש והושם המרה עליו היו' ההוא הקדוש הנה זה הוא מה שנראה לנו בעניין אלו המוספין והוא נפלא מאד כמו שתראה והוא מעיד מאד על אמתת מה שזכרנו בכונות הקרבנות והטומאות וגם מה שזכרנו מענינם במה שקדם מעיד על אמתת מה שאמרנו בזה המקום וזהו על דרך האמת שהוא מעיד לעצמו מכל צד ומכל פנה יתברך היכול אשר גלה לנו סודו באלו העמוקות ויתרומם על כל ברכה ותהלה:

@170 **ויד ה' היתה אל אליהו.** ר"ל שכבר בא אליו דבר ה' שיעשה זה ר"ל לשנס מתניו ולרוץ לפני אחאב עד שבא אחאב ליזרעאל והנה שנוס מתניו הוא שחגר מתניו בדרך שיתכן לו לרוץ בזולת נזק באבריו הפנימיים מפני חוזק התנועה:
@171 **את כל אשר עשה אליהו.** הוא מה שעשה להוריד האש על העולה בדרך שאכלה העולה והעצים והאבנים והמים אשר בתעלה לחכה לבחון כי ה' הוא האלהי' ומה שעשה מהבאת המטר: **ואת כל אשר הרג את כל הנביאים בחרב.** ידמה שהודיע לה שהוא צוה לתפשם כלם ולהורידם לנחל קישון ושחטם שם כאילו רצה שלא יטמא דמם את הארץ ולזה נשפך דמם אל הנחל שיוליכהו למקום רחוק:
@172 **כה יעשון אלהים.** אמרה זה בלשון רבים לרבוי האלוהות אשר היו עובדים להם:
@173 **וירא ויקם וילך אל נפשו.** ר"ל שכאשר ראה הסכנה שהוא בה לא רצה לסמוך על הנס אבל קם תכף והלך למלט את נפשו: **ויבא באר שבע אשר ליהודה.** ר"ל שכבר היה למלך יהודה ולזה בא שם להמלט מיד איזבל ואע"פ שבא לנחלת בני שמעון הנה ידמה כי מפני היותו תוך ערי יהודה היו בני העיר ההיא תחת מלך יהודה או אולי במלחמות שנלחמו מלכי יהודה עם מלכי ישראל לקחו מלכי יהודה העיר הזאת:
@174 **והוא הלך במדבר דרך יום.** בחר ללכת במדבר כדי שלא יראהו איש שיוכל להגיד זה לאיזבל: **וישב תחת רותם אחד.** הוא עץ שפל גיני"שטה בלע"ז: **וישאל את נפשו למות.** הנה מחוזק הרעב היה בוחר במות ולזה אמר כי רב לו במה שחיה ובקש מהש"י שיקח את נפשו וימיתהו כי לא טוב הוא מאבותיו שיזכה מפני זה לאורך הנפלא מן החיים:
@176 **עוגת רצפים.** ר"ל עוגה שנאפית ברצפי אש:
@178 **וילך בכח האכילה ההיא.** ר"ל בכח שקנה מהאכילה ההיא הלך ארבעים יום וארבעים לילה ואולם אמר שקנה הכח מהאכילה ההיא כי קודם האכילה היה חלוש מאד והיה קרוב מאד למות מפני הרעב, והנה בא בדרך המדבר עד הר חורב שנתנה בו התורה לישראל:
@179 **ויבא שם אל המערה וילן שם.** ידמה שכבר היתה מערה בהר חורב ולן שם אליהו: **והנה דבר ה' אליו ויאמר.** אחשוב כי בתחלה בא אליו דבר ה' על דרך הנבואה ושאל לו הש"י מה לך פה אליהו ואע"פ שכבר ידע זה הש"י על דרך אמרו לקין אי הבל אחיך והנה השיב אליהו כי הוא מקנא לש"י כי בני ישראל עזבו את ברית התורה והרסו מזבחות הש"י כי לא רצו לעבוד כי אם אלהים אחרים והרגו נביאי השם בחרב כי כבר הרגה אות' איזבל כמו שקדם ונשאר אליהו לבדו מן הנביאים הידועים לה ובקשה להרוג אותו וכאילו שאל מהש"י על זה שיקום נקמתו על אלו הרעות שעשו ישראל והנה קרה זה לאליהו מרוב כעסו על חטאת ישראל אז אמר לו הש"י שיצא ויעמוד בהר לפני ה' ר"ל כי כשיראה לו כבוד ה' אז יצא מהמערה וידמ' שכבר עשה זה הש"י כדי שיבקש אליהו רחמים על ישראל לא שיתפלל להשחיתם על רוע מעלליהם כי היה רצון הש"י להאריך להם אפו כדי שישובו אליו ולזה הראה לו הדברים המשחיתים כמו הרוח הגדולה והחזקה שהיא מפרקת הרים ומשברת סלעים:
@181 **ולא** היה ברוח ה' כי אין מדרך הש"י שיביא הרעות אם לא לתכלית שיגיע מהם טוב ולפי שנתבאר לש"י שלא יהיו מקבלי' תוכחת לא רצה לענשם על אלו החטאים לפי מה שראוי אבל המתין להם אם ישובו מדרכם הרעה, והנה היה אחר הרוח רעש והוא מזיק כי הוא כלי להפכת הארצות, וזכר ג"כ שלא ברעש ה' כמו שזכרנו ברוח:
@182 והנה אחר הרעש אש שהוא יותר מזיק. וזכר ג"כ כי לא באש השם לסבה שזכרנו וכאילו באר בזה שאלו הרעות שיבאו להם בהדרגה אינם מכוונות מהש"י אך הסתיר פניו מהם ועזבם כמו מטרה לחצי הרעות הנכונות לבא עליהם היה זה כן לפי שהרעו' הבאות על צד הקנאת המוסר לא יועילו להם הלא תראה כי מפני עצירת הטל והמטר שלש שנים לא נכנעו מפני הש"י: **והנה אחר האש קול דממה דקה.** ר"ל קול נמוך מהש"י כאילו הוא מורכב מהקול והשתיקה והנה העיר בזה כי אחר נפלם באלו הרעות ולא ירגישו שעונותיהם הטו שיהיו משולחים ונעזבים למקרי הזמן הנה יבא להם מוסר מה מהשם ית' אך לא יהיה שלם באופן שהיה מביא השם ית' המוסר לישראל במדבר בימי משה שהיה מגיע באופן שהיו מרגישי' תכף כי בסבת העון היה אך יהיה בזה הענין כמו מורכב מהקול ומהשתיקה, וידמה כי מרוב כעס אליהו על רוב חטאת ישראל לא שם אל לבו להבין את דבר המראה הזאת ולזה השיב אופן שאמר בראשונה:
@183 **ויהי כשמוע אליהו.** ר"ל כשמוע אליהו קול הש"י הסתיר פניו מהביט אל האלהים ולזה כסה פניו באדרת שהיה לבוש בה ויצא מהמערה כמו שצוהו השם ית' ועמד פתח המערה:
@185 **ויאמר ה' אליו לך לדרכך מדברה דמשק.** ר"ל שילך לדרכו אל מדבר דמשק ומשם ימשח חזאל למלך על ארם והרצון בזה היותו נבחר למלך על ארם ומשם ימשח יהוא בן נמשי למלך על ישראל ומשם ימשח אלישע בן שפט מאבל מחולה לנביא תחת אליהו אחר שאין רצון אליהו להיות לנביאו ולמזהיר לישראל עד שכבר קץ בחייו מפני רוע מעשיהם ואמר לש"י שיקח את נפשו, ולפי שלא מצא שם בדרך כי אם אלישע בן שפט השליך אדרתו עליו לעשות לו סימן שיהיה נביא וילבש נבואת אליהו עם שלביש' האדרת היתה סימן לנביא ולזה אמר הכתוב ולא ילבשו עוד אדרת שער למען כחש וידמה שהודיע אליהו לאלישע את הנבואה וצוהו שיודיע לחזאל שהוא יהיה מלך על ארם ושימשח יהוא בן נמשי למלך על ישראל ולזה היה כאילו ימשחם אליהו או יהיה הרצון בזה כי מפני רצון אליהו בעונש ישראל לפי מה שיורה מה שלמד עליהם חובה לפני הש"י הנה הוא סבת המשח חזאל למלך על ארם ומשח יהוא למלך על ישראל והמשח אלישע לנביא תחתיו ולזה אמר לו הש"י בכל אלו הדברים ומשחת כי הוא סבת המשחם כמו שזכרנו:
@187 **והנה** ימית יהוא רבים כי הוא השמיד כל בית אחאב והרג כל עובדי הבעל ונביאיו כהניו והרג איזבל אשר עליה אמר אליהו קצת אלו הדברי' לש"י ומה שאמר כי הנמלט מחרב חזאל ימית יהוא אין הרצון בו שיקדם הרע שיעשה חזאל לישראל אל הרע שיעשה יהוא לישראל כי היה הענין בהפך זה כי בימי יהואחז בן יהוא היה הרע שעשה חזאל לישראל אך הרצון בו שמה שהיה נמלט מחרב חזאל אם היו חיים ימית יהוא כי ידמה שלא היה כח לחזאל בבית אחאב לו היה קיים כי אחאב ובניו הם היו מצליחים תמיד כנגד מלך ארם, וכן מה שאמר והנמלט מחרב יהוא ימית אלישע אין הרצון בו שיקדם הרע שעשה יהוא לישראל על הרע שיתחדש להם בסבת אלישע כי הדבר היה בהפך והנה מה שהמית אלישע הוא ארבעים ושנים נערים שקללם בה' וידמה שהרעב החזק אשר היה בשמרון היה בסבת אלישע ולזה אמר המלך כה יעשה לי אלהים וכה יוסיף אם יעמוד ראש אלישע בן שפט עליו היום:
@188 וזכר שכבר יגיע זה הרע לשיעור שלא ישארו בישראל כי אם שבעת אלפים איש והם אשר לא כרעו לבעל ולא נשקו לו, והנה אמר יהוא בן נמשי והוא אבי אביו כי כבר יקרא אבי האב אב כאמרו ותבאנה אל רעואל אביהן:
@189 והוא חורש שנים עשר צמדים לפניו והוא בשנים העשר. ר"ל שהיו שם שנים עשר חורשי' והיו לכל אחד מהם צמד בקר ואלישע היה חורש כי הוא היה אחד מהשנים העשר החורשים, ואחשוב שזכר זה להעיד כי אבי אלישע היה עשיר מאד ועם כ"ז נפרד אלישע מבית אביו לשרת אליהו מפני חוזק אהבתו החכמה: **ויעבר אליהו אליו וישלך אדרתו אליו.** ר"ל כי כבר עבר אליהו סמוך לו ובהיותו קרוב אליו מאד השליך כנפי אדרתו עליו על שכבר הסך אדרתו עליו מדי עברו והנה הרגיש תכף אלישע כי רצון אליהו היה אליו שיבא ויחסה תחת כנפיו ולזה עזב את הבקר ורץ אחרי אליהו ואמר לו שיעזבהו לנשק אביו ואמו ואחר ילך אחרי אליהו:
@190 **ויאמר לו לך שוב כי מה עשיתי לך.** ירצה לפי מה שאחשוב לך לנשק אביך ואמך ושוב אחרי כי זה הוא מה שעשיתי לך ר"ל שכבר עשיתי זה להעיר אותך שתבא לחסות תחת כנפי:
@191 **ובכלי הבקר בשלם הבשר.** ר"ל בשל להם הבשר וכאשר נתבשל נתן לעם אשר בשדה ואכלו וקם והלך אחרי אליהו ושרתו כדי שילמד יותר מחכמתו ממה שילמדו שאר תלמידיו כי המשרת הוא תמיד עם הרב ורואה מנהגיו ושומע דבריו תמיד וילמד יותר ממה שילמד התלמיד שאינו משרת:
